    input  clk,
    input  a,
    input  b,
    output out_assign,
    output out_always_comb,
    output reg out_always_ff
);

    // XOR using a continuous assign statement
    assign out_assign = a ^ b;

    // XOR using a combinational always block
    reg out_comb_reg;
    always @(*) begin
        out_comb_reg = a ^ b;
    end
    assign out_always_comb = out_comb_reg;

    // XOR using a clocked always block (output is delayed by one flip-flop)
    always @(posedge clk) begin
        out_always_ff <= a ^ b;
    end

