module TopModule (
    input  clk,
    input  enable,
    input  S,
    input  A,
    input  B,
    input  C,
    output Z
);

    reg [7:0] Q;

    // 8-bit shift register: S feeds Q[0], shifts toward Q[7] when enable is high
    always @(posedge clk) begin
        if (enable)
            Q <= {Q[6:0], S};
    end

    // 8:1 multiplexer tree, selected by {A,B,C} (A is MSB)
    wire m0 = C ? Q[1] : Q[0];  // AB = 00
    wire m1 = C ? Q[3] : Q[2];  // AB = 01
    wire m2 = C ? Q[5] : Q[4];  // AB = 10
    wire m3 = C ? Q[7] : Q[6];  // AB = 11

    wire n0 = B ? m1 : m0;      // A = 0
    wire n1 = B ? m3 : m2;      // A = 1

    assign Z = A ? n1 : n0;

endmodule

