module TopModule (
    input  clk,
    input  areset,
    input  x,
    output z
);

    // One-hot state encoding
    reg stA, stB;

    // Next-state logic
    wire nA = stA & ~x;
    wire nB = (stA & x) | stB;

    // Sequential logic: asynchronous active-high reset into state A
    always @(posedge clk or posedge areset) begin
        if (areset) begin
            stA <= 1'b1;
            stB <= 1'b0;
        end else begin
            stA <= nA;
            stB <= nB;
        end
    end

    // Mealy output logic
    assign z = (stA & x) | (stB & ~x);

endmodule

