module TopModule (
    input  clk,
    input  reset,
    input  w,
    output z
);
    localparam [2:0] A = 3'd0,
                     B = 3'd1,
                     C = 3'd2,
                     D = 3'd3,
                     E = 3'd4,
                     F = 3'd5;

    reg [2:0] present_state;
    reg [2:0] next_state;

    // State table (combinational next-state logic)
    always @(*) begin
        case (present_state)
            A: next_state = w ? B : A;
            B: next_state = w ? C : D;
            C: next_state = w ? E : D;
            D: next_state = w ? F : A;
            E: next_state = w ? E : D;
            F: next_state = w ? C : D;
            default: next_state = A;
        endcase
    end

    // State flip-flops (synchronous, active-high reset to A)
    always @(posedge clk) begin
        if (reset)
            present_state <= A;
        else
            present_state <= next_state;
    end

    // Moore output: z = 1 in states E and F
    assign z = (present_state == E) || (present_state == F);

endmodule

