module TopModule (
    input clk,
    input load,
    input [255:0] data,
    output reg [255:0] q
);

    reg [255:0] nxt;
    reg [3:0] n;
    integer r, c, dr, dc;

    always @(*) begin
        for (r = 0; r < 16; r = r + 1) begin
            for (c = 0; c < 16; c = c + 1) begin
                n = 4'd0;
                for (dr = -1; dr <= 1; dr = dr + 1) begin
                    for (dc = -1; dc <= 1; dc = dc + 1) begin
                        if (!(dr == 0 && dc == 0))
                            n = n + q[((r + dr + 16) % 16) * 16 + ((c + dc + 16) % 16)];
                    end
                end
                nxt[r * 16 + c] = (n == 4'd3) | (q[r * 16 + c] & (n == 4'd2));
            end
        end
    end

    always @(posedge clk) begin
