module TopModule (
    input  wire       clk,
    input  wire       in,
    input  wire       reset,
    output reg  [7:0] out_byte,
    output reg        done
);

    localparam IDLE = 2'd0;  // Wait for start bit (0)
    localparam DATA = 2'd1;  // Receive 8 data bits, LSB first
    localparam STOP = 2'd2;  // Check stop bit (1)
    localparam WAIT = 2'd3;  // Framing error: wait for line to return to 1

    reg [1:0] state;
    reg [2:0] count;

    always @(posedge clk) begin
        if (reset) begin
            state    <= IDLE;
            count    <= 3'd0;
            out_byte <= 8'd0;
            done     <= 1'b0;
        end
        else begin
            done <= 1'b0;

            case (state)
                IDLE: begin
                    if (!in) begin
                        state <= DATA;
                        count <= 3'd0;
                    end
                end

                DATA: begin
                    // Shift in LSB first: new bit enters at MSB, so after 8 shifts
                    // the first bit received ends up at bit 0.
                    out_byte <= {in, out_byte[7:1]};
                    count    <= count + 3'd1;
                    if (count == 3'd7)
                        state <= STOP;
                end

                STOP: begin
                    if (in) begin
                        done  <= 1'b1;
                        state <= IDLE;
                    end
                    else begin
                        // Stop bit missing: wait for a 1 before receiving again
                        state <= WAIT;
                    end
                end

                WAIT: begin
                    if (in)
                        state <= IDLE;
                end

                default: state <= IDLE;
            endcase
        end
    end

endmodule

