module TopModule (
    input  clk,
    input  reset,
    input  data,
    input  done_counting,
    input  ack,
    output shift_ena,
    output counting,
    output done
);

    localparam [2:0] IDLE     = 3'd0,
                     S1       = 3'd1,
                     S11      = 3'd2,
                     S110     = 3'd3,
                     SHIFT    = 3'd4,
                     COUNT    = 3'd5,
                     NOTIFY   = 3'd6;

    reg [2:0] state, next_state;
    reg [1:0] cnt;

    // State register with synchronous active-high reset
    always @(posedge clk) begin
        if (reset)
            state <= IDLE;
        else
            state <= next_state;
    end

    // Shift counter: counts 4 cycles while in SHIFT state
    always @(posedge clk) begin
        if (reset)
            cnt <= 2'd0;
        else if (state == SHIFT)
            cnt <= cnt + 2'd1;
        else
            cnt <= 2'd0;
    end

    // Next-state logic
    always @(*) begin
        next_state = state;
        case (state)
            IDLE: begin
                if (data)
                    next_state = S1;
                else
                    next_state = IDLE;
            end
            S1: begin
                if (data)
                    next_state = S11;
                else
                    next_state = IDLE;
            end
            S11: begin
                if (data)
                    next_state = S11;
                else
                    next_state = S110;
            end
            S110: begin
                if (data)
                    next_state = SHIFT;
                else
                    next_state = IDLE;
            end
            SHIFT: begin
                if (cnt == 2'd3)
                    next_state = COUNT;
                else
                    next_state = SHIFT;
            end
            COUNT: begin
                if (done_counting)
                    next_state = NOTIFY;
                else
                    next_state = COUNT;
            end
            NOTIFY: begin
                if (ack)
                    next_state = IDLE;
                else
                    next_state = NOTIFY;
            end
            default: next_state = IDLE;
        endcase
    end

    // Moore outputs
    assign shift_ena = (state == SHIFT);
    assign counting  = (state == COUNT);
    assign done      = (state == NOTIFY);

endmodule

