module TopModule (
    input  clk,
    input  reset,
    input  [2:0] s,
    output fr2,
    output fr1,
    output fr0,
    output dfr
);

    // Water level: 3 = above s[2], 2 = between s[2] and s[1],
    //              1 = between s[1] and s[0], 0 = below s[0]
    wire [1:0] lvl = {1'b0, s[0]} + {1'b0, s[1]} + {1'b0, s[2]};

    // Registered previous level and direction of last sensor change
    // (1 = last change was a rise in level, 0 = fall)
    reg [1:0] prev_lvl;
    reg       up_r;

    always @(posedge clk) begin
        if (reset) begin
            prev_lvl <= 2'd0;   // as if water had been low for a long time
            up_r     <= 1'b1;   // all four outputs asserted
        end else begin
            if (lvl > prev_lvl)
                up_r <= 1'b1;
            else if (lvl < prev_lvl)
                up_r <= 1'b0;
            prev_lvl <= lvl;
        end
    end

    // Nominal flow valves
    assign fr0 = (lvl < 2'd3);
    assign fr1 = (lvl < 2'd2);
    assign fr2 = (lvl < 2'd1);

    // Supplemental flow valve: open on rising level, or at maximum flow
    // (below s[0]); closed when level is above s[2] (zero flow)
    assign dfr = (lvl != 2'd3) & (up_r | (lvl == 2'd0));

endmodule

