module TopModule (
    input  clk,
    input  areset,
    input  bump_left,
    input  bump_right,
    input  ground,
    input  dig,
    output walk_left,
    output walk_right,
    output aaah,
    output digging
);

    localparam [2:0] WL = 3'd0,  // walking left
                     WR = 3'd1,  // walking right
                     FL = 3'd2,  // falling, will resume walking left
                     FR = 3'd3,  // falling, will resume walking right
                     DL = 3'd4,  // digging, direction left
                     DR = 3'd5;  // digging, direction right

    reg [2:0] state, next_state;

    // State register with positive-edge asynchronous reset to walk left
    always @(posedge clk or posedge areset) begin
        if (areset)
            state <= WL;
        else
            state <= next_state;
    end

    // Next-state logic: fall > dig > switch direction
    always @(*) begin
        next_state = state;
        case (state)
            WL: begin
                if (!ground)          next_state = FL;
                else if (dig)         next_state = DL;
                else if (bump_left)   next_state = WR;
                else                  next_state = WL;
            end
            WR: begin
                if (!ground)          next_state = FR;
                else if (dig)         next_state = DR;
                else if (bump_right)  next_state = WL;
                else                  next_state = WR;
            end
            FL: begin
                if (ground)           next_state = WL;
                else                  next_state = FL;
            end
            FR: begin
                if (ground)           next_state = WR;
                else                  next_state = FR;
            end
            DL: begin
                if (!ground)          next_state = FL;
                else                  next_state = DL;
            end
            DR: begin
                if (!ground)          next_state = FR;
                else                  next_state = DR;
            end
            default: next_state = WL;
        endcase
    end

    // Moore outputs depend only on the current state
    assign walk_left  = (state == WL);
    assign walk_right = (state == WR);
    assign aaah       = (state == FL) || (state == FR);
    assign digging    = (state == DL) || (state == DR);

endmodule

