module TopModule (
    input  clock,
    input  a,
    output p,
    output q
);
    reg p_reg;
    reg q_reg;

    // p is transparent while clock is high
    always @(clock or a) begin
        if (clock)
            p_reg <= a;
    end

    // q is transparent while clock is low
    always @(clock or p_reg) begin
        if (!clock)
            q_reg <= p_reg;
    end

    assign p = p_reg;
    assign q = q_reg;
endmodule

