module TopModule (
    input  wire       clk,
    input  wire       reset,
    input  wire       data,
    output reg  [3:0] count,
    output wire       counting,
    output wire       done,
    input  wire       ack
);

    localparam [2:0] S_IDLE  = 3'd0,  // searching, no prefix matched
                     S_S1    = 3'd1,  // matched "1"
                     S_S2    = 3'd2,  // matched "11"
                     S_S3    = 3'd3,  // matched "110"
                     S_SHIFT = 3'd4,  // shifting in 4-bit delay
                     S_COUNT = 3'd5,  // counting
                     S_DONE  = 3'd6;  // timed out, waiting for ack

    reg [2:0] state;
    reg [1:0] bitcnt;
    reg [9:0] sub;   // counts 0..999 clock cycles

    assign counting = (state == S_COUNT);
    assign done     = (state == S_DONE);

    always @(posedge clk) begin
        if (reset) begin
            state  <= S_IDLE;
            bitcnt <= 2'd0;
            sub    <= 10'd0;
            count  <= 4'd0;
        end else begin
            case (state)
                S_IDLE: begin
                    if (data) state <= S_S1;
                end

                S_S1: begin
                    if (data) state <= S_S2;
                    else      state <= S_IDLE;
                end

                S_S2: begin
                    if (!data) state <= S_S3;
                end

                S_S3: begin
                    if (data) begin
                        state  <= S_SHIFT;
                        bitcnt <= 2'd0;
                    end else begin
                        state <= S_IDLE;
                    end
                end

                S_SHIFT: begin
                    count  <= {count[2:0], data};
                    bitcnt <= bitcnt + 2'd1;
                    if (bitcnt == 2'd3) begin
                        state <= S_COUNT;
                        sub   <= 10'd0;
                    end
                end

                S_COUNT: begin
                    if (sub == 10'd999) begin
                        sub <= 10'd0;
                        if (count == 4'd0) begin
                            state <= S_DONE;
                        end else begin
                            count <= count - 4'd1;
                        end
                    end else begin
                        sub <= sub + 10'd1;
                    end
                end

                S_DONE: begin
                    if (ack) state <= S_IDLE;
                end

                default: state <= S_IDLE;
            endcase
        end
    end

endmodule

