module TopModule (
    input  clk,
    input  areset,
    input  bump_left,
    input  bump_right,
    input  ground,
    input  dig,
    output walk_left,
    output walk_right,
    output aaah,
    output digging
);

    localparam [2:0] WL  = 3'd0,   // walking left
                     WR  = 3'd1,   // walking right
                     FL  = 3'd2,   // falling, was walking left
                     FR  = 3'd3,   // falling, was walking right
                     DL  = 3'd4,   // digging, was walking left
                     DR  = 3'd5,   // digging, was walking right
                     SPL = 3'd6;   // splattered (terminal until reset)

    reg [2:0] state, next;
    reg [4:0] cnt;   // counts clock cycles spent falling (saturates at 31)

    wire falling = (state == FL) || (state == FR);

    // State register (asynchronous reset to walking left)
    always @(posedge clk or posedge areset) begin
        if (areset)
            state <= WL;
        else
            state <= next;
    end

    // Fall-duration counter
    always @(posedge clk or posedge areset) begin
        if (areset)
            cnt <= 5'd0;
        else if (falling && !ground) begin
            if (cnt != 5'd31)
                cnt <= cnt + 5'd1;
        end
        else
            cnt <= 5'd0;
    end

    // Next-state logic
    // Priority when walking: fall > dig > switch direction
    always @(*) begin
        next = state;
        case (state)
            WL: begin
                if (!ground)
                    next = FL;
                else if (dig)
                    next = DL;
                else if (bump_left)
                    next = WR;
            end
            WR: begin
                if (!ground)
                    next = FR;
                else if (dig)
                    next = DR;
                else if (bump_right)
                    next = WL;
            end
            DL: begin
                if (!ground)
                    next = FL;
            end
            DR: begin
                if (!ground)
                    next = FR;
            end
            FL: begin
                if (ground)
                    next = (cnt > 5'd20) ? SPL : WL;
            end
            FR: begin
                if (ground)
                    next = (cnt > 5'd20) ? SPL : WR;
            end
            SPL: begin
                next = SPL;
            end
            default: next = WL;
        endcase
    end

    // Moore outputs
    assign walk_left  = (state == WL);
    assign walk_right = (state == WR);
    assign aaah       = falling;
    assign digging    = (state == DL) || (state == DR);

endmodule

