module TopModule (
    input  clk,
    input  areset,
    input  x,
    output z
);

    // One-hot state encoding
    localparam A = 0;
    localparam B = 1;

    reg [1:0] state;
    reg [1:0] next_state;

    // Next-state logic
    always @(*) begin
        next_state[A] = state[A] & ~x;
        next_state[B] = (state[A] & x) | state[B];
    end

    // State register with asynchronous active-high reset
    always @(posedge clk or posedge areset) begin
        if (areset)
            state <= 2'b01;
        else
            state <= next_state;
    end

    // Mealy output logic
    assign z = (state[A] & x) | (state[B] & ~x);

endmodule

