module TopModule (
    input  clk,
    input  reset,
    input  data,
    output start_shifting
);

    localparam S0    = 3'd0;  // no match
    localparam S1    = 3'd1;  // seen 1
    localparam S11   = 3'd2;  // seen 11
    localparam S110  = 3'd3;  // seen 110
    localparam FOUND = 3'd4;  // seen 1101

    reg [2:0] state, next_state;

    always @(*) begin
        case (state)
            S0:      next_state = data ? S1 : S0;
            S1:      next_state = data ? S11 : S0;
            S11:     next_state = data ? S11 : S110;
            S110:    next_state = data ? FOUND : S0;
            FOUND:   next_state = FOUND;
            default: next_state = S0;
        endcase
    end

    always @(posedge clk) begin
        if (reset)
            state <= S0;
        else
            state <= next_state;
    end

    assign start_shifting = (state == FOUND);

endmodule

