               B = 2'd1,  // first 1 just received, output 1
               C = 2'd2,  // 1 already seen, last input 1, output 0
               D = 2'd3;  // 1 already seen, last input 0, output 1

    reg [1:0] state, next_state;

    always @(posedge clk or posedge areset) begin
        if (areset)
            state <= A;
        else
            state <= next_state;
    end

    always @(*) begin
        case (state)
            A: next_state = x ? B : A;
            default: next_state = x ? C : D;
        endcase
    end

    assign z = (state == B) || (state == D);

