module TopModule (
    input clk,
    input load,
    input [511:0] data,
    output reg [511:0] q
);

    wire [511:0] left;   // left[i]  = q[i+1]
    wire [511:0] right;  // right[i] = q[i-1]

    assign left  = {1'b0, q[511:1]};
    assign right = {q[510:0], 1'b0};

    // Rule 110 next state:
    // L C R -> next
    // 111->0, 110->1, 101->1, 100->0, 011->1, 010->1, 001->1, 000->0
    // next = (C ^ R) | (~L & C)  ... simplified below
    wire [511:0] next_q;
    assign next_q = (q ^ right) | (~left & q);

    always @(posedge clk) begin
        if (load)
            q <= data;
        else
            q <= next_q;
    end

