module TopModule (
    input  clk,
    input  reset,
    input  in,
    output done
);

    localparam IDLE  = 3'd0;
    localparam DATA  = 3'd1;
    localparam STOP  = 3'd2;
    localparam DONE  = 3'd3;
    localparam WAIT  = 3'd4;

    reg [2:0] state, next_state;
    reg [2:0] cnt;

    always @(*) begin
        case (state)
            IDLE: next_state = in ? IDLE : DATA;
            DATA: next_state = (cnt == 3'd7) ? STOP : DATA;
            STOP: next_state = in ? DONE : WAIT;
            DONE: next_state = in ? IDLE : DATA;
            WAIT: next_state = in ? IDLE : WAIT;
            default: next_state = IDLE;
        endcase
    end

    always @(posedge clk) begin
        if (reset) begin
            state <= IDLE;
            cnt   <= 3'd0;
        end else begin
            state <= next_state;
            if (state == DATA)
                cnt <= (cnt == 3'd7) ? 3'd0 : cnt + 3'd1;
            else
                cnt <= 3'd0;
        end
    end

    assign done = (state == DONE);

endmodule

