module TopModule (
    input  clk,
    input  reset,
    input  in,
    output disc,
    output flag,
    output err
);

    localparam S0   = 4'd0;  // zero seen (or reset)
    localparam S1   = 4'd1;  // one 1
    localparam S2   = 4'd2;  // two 1s
    localparam S3   = 4'd3;  // three 1s
    localparam S4   = 4'd4;  // four 1s
    localparam S5   = 4'd5;  // five 1s
    localparam S6   = 4'd6;  // six 1s
    localparam S7   = 4'd7;  // seven or more 1s (error)
    localparam SDIS = 4'd8;  // 0111110 detected
    localparam SFLG = 4'd9;  // 01111110 detected

    reg [3:0] state, next_state;

    always @(*) begin
        case (state)
            S0:      next_state = in ? S1 : S0;
            S1:      next_state = in ? S2 : S0;
            S2:      next_state = in ? S3 : S0;
            S3:      next_state = in ? S4 : S0;
            S4:      next_state = in ? S5 : S0;
            S5:      next_state = in ? S6 : SDIS;
            S6:      next_state = in ? S7 : SFLG;
            S7:      next_state = in ? S7 : S0;
            SDIS:    next_state = in ? S1 : S0;
            SFLG:    next_state = in ? S1 : S0;
            default: next_state = S0;
        endcase
    end

    always @(posedge clk) begin
        if (reset)
            state <= S0;
        else
            state <= next_state;
    end

    assign disc = (state == SDIS);
    assign flag = (state == SFLG);
    assign err  = (state == S7);

endmodule

