                    else begin
                        mm[3:0] <= mm[3:0] + 4'd1;
                    end
                end
                else begin
                    ss[7:4] <= ss[7:4] + 4'd1;
                end
            end
            else begin
                ss[3:0] <= ss[3:0] + 4'd1;
            end
        end
    end

