module TopModule (
    input clk,
    input reset,
    input [2:0] s,
    output fr2,
    output fr1,
    output fr0,
    output dfr
);

    reg [2:0] prev;
    reg       up;

    always @(posedge clk) begin
        if (reset) begin
            prev <= 3'b000;
            up   <= 1'b1;
        end else begin
            if (s > prev)
                up <= 1'b1;
            else if (s < prev)
                up <= 1'b0;
            prev <= s;
        end
    end

    reg [2:0] fr;

    always @(*) begin
        case (prev)
            3'b000:  fr = 3'b111;
            3'b001:  fr = 3'b011;
            3'b011:  fr = 3'b001;
            3'b111:  fr = 3'b000;
            default: fr = 3'b111;
        endcase
    end

    assign fr2 = fr[2];
    assign fr1 = fr[1];
    assign fr0 = fr[0];
    assign dfr = up | (prev == 3'b000);

endmodule

