module TopModule (
    input        clk,
    input        reset,
    input        data,
    output [3:0] count,
    output       counting,
    output       done,
    input        ack
);

    localparam S_IDLE  = 3'd0;
    localparam S_1     = 3'd1;
    localparam S_11    = 3'd2;
    localparam S_110   = 3'd3;
    localparam S_SHIFT = 3'd4;
    localparam S_COUNT = 3'd5;
    localparam S_DONE  = 3'd6;

    reg [2:0] state;
    reg [3:0] delay_cnt;
    reg [1:0] shift_cnt;
    reg [9:0] cycle_cnt;

    assign count    = delay_cnt;
    assign counting = (state == S_COUNT);
    assign done     = (state == S_DONE);

    always @(posedge clk) begin
        if (reset) begin
            state     <= S_IDLE;
            delay_cnt <= 4'd0;
            shift_cnt <= 2'd0;
            cycle_cnt <= 10'd0;
        end else begin
            case (state)
                S_IDLE: begin
                    if (data) state <= S_1;
                    else      state <= S_IDLE;
                end
                S_1: begin
                    if (data) state <= S_11;
                    else      state <= S_IDLE;
                end
                S_11: begin
                    if (data) state <= S_11;
                    else      state <= S_110;
                end
                S_110: begin
                    if (data) begin
                        state     <= S_SHIFT;
                        shift_cnt <= 2'd0;
                    end else begin
                        state <= S_IDLE;
                    end
                end
                S_SHIFT: begin
                    delay_cnt <= {delay_cnt[2:0], data};
                    shift_cnt <= shift_cnt + 2'd1;
                    if (shift_cnt == 2'd3) begin
                        state     <= S_COUNT;
                        cycle_cnt <= 10'd0;
                    end
                end
                S_COUNT: begin
                    if (cycle_cnt == 10'd999) begin
                        cycle_cnt <= 10'd0;
                        if (delay_cnt == 4'd0) begin
                            state <= S_DONE;
                        end else begin
                            delay_cnt <= delay_cnt - 4'd1;
                        end
                    end else begin
                        cycle_cnt <= cycle_cnt + 10'd1;
                    end
                end
                S_DONE: begin
                    if (ack) state <= S_IDLE;
                end
                default: state <= S_IDLE;
            endcase
        end
    end

endmodule

