module TopModule (
    input  clk,
    input  areset,
    input  bump_left,
    input  bump_right,
    input  ground,
    input  dig,
    output walk_left,
    output walk_right,
    output aaah,
    output digging
);

    localparam WL = 3'd0,
               WR = 3'd1,
               FL = 3'd2,
               FR = 3'd3,
               DL = 3'd4,
               DR = 3'd5,
               SP = 3'd6;

    reg [2:0] state, next;
    reg [4:0] cnt;

    always @(*) begin
        next = state;
        case (state)
            WL: begin
                if (!ground)         next = FL;
                else if (dig)        next = DL;
                else if (bump_left)  next = WR;
                else                 next = WL;
            end
            WR: begin
                if (!ground)         next = FR;
                else if (dig)        next = DR;
                else if (bump_right) next = WL;
                else                 next = WR;
            end
            FL: begin
                if (ground) begin
                    if (cnt >= 5'd20) next = SP;
                    else              next = WL;
                end else              next = FL;
            end
            FR: begin
                if (ground) begin
                    if (cnt >= 5'd20) next = SP;
                    else              next = WR;
                end else              next = FR;
            end
            DL: begin
                if (!ground) next = FL;
                else         next = DL;
            end
            DR: begin
                if (!ground) next = FR;
                else         next = DR;
            end
            SP: next = SP;
            default: next = WL;
        endcase
    end

    always @(posedge clk or posedge areset) begin
        if (areset)
            state <= WL;
        else
            state <= next;
    end

    always @(posedge clk or posedge areset) begin
        if (areset)
            cnt <= 5'd0;
        else if (state == FL || state == FR) begin
            if (cnt < 5'd20)
                cnt <= cnt + 5'd1;
        end else
            cnt <= 5'd0;
    end

    assign walk_left  = (state == WL);
    assign walk_right = (state == WR);
    assign aaah       = (state == FL) || (state == FR);
    assign digging    = (state == DL) || (state == DR);

endmodule

