module TopModule (
  input         clk,
  input         reset,
  output [3:1]  ena,
  output reg [15:0] q
);

  assign ena[1] = (q[3:0] == 4'd9);
  assign ena[2] = (q[7:4] == 4'd9) && ena[1];
  assign ena[3] = (q[11:8] == 4'd9) && ena[2];

  always @(posedge clk) begin
    if (reset) begin
      q <= 16'd0;
    end else begin
      // ones digit
      if (q[3:0] == 4'd9)
        q[3:0] <= 4'd0;
      else
        q[3:0] <= q[3:0] + 4'd1;

      // tens digit
      if (ena[1]) begin
        if (q[7:4] == 4'd9)
          q[7:4] <= 4'd0;
        else
          q[7:4] <= q[7:4] + 4'd1;
      end

      // hundreds digit
      if (ena[2]) begin
