module TopModule (
  input  clk,
  input  areset,
  input  x,
  output z
);

  // One-hot state encoding: state[0] = A, state[1] = B
  reg [1:0] state;
  wire [1:0] next_state;

  assign next_state[0] = state[0] & ~x;
  assign next_state[1] = (state[0] & x) | state[1];

  always @(posedge clk or posedge areset) begin
    if (areset)
      state <= 2'b01;
    else
      state <= next_state;
  end

  // Mealy output
  assign z = (state[0] & x) | (state[1] & ~x);

endmodule

