  input  clk,
  input  areset,
  input  bump_left,
  input  bump_right,
  input  ground,
  output walk_left,
  output walk_right,
  output aaah
);

  localparam LEFT    = 2'd0,
             RIGHT   = 2'd1,
             FALL_L  = 2'd2,
             FALL_R  = 2'd3;

  reg [1:0] state, next_state;

