module TopModule (
    input clk,
    input load,
    input [255:0] data,
    output reg [255:0] q
);

    reg [255:0] next_q;
    integer r, c;
    integer rm, rp, cm, cp;
    reg [3:0] cnt;

    always @(*) begin
        for (r = 0; r < 16; r = r + 1) begin
            for (c = 0; c < 16; c = c + 1) begin
                rm = (r + 15) % 16;
                rp = (r + 1) % 16;
                cm = (c + 15) % 16;
                cp = (c + 1) % 16;
                cnt = q[rm*16+cm] + q[rm*16+c] + q[rm*16+cp]
                    + q[r*16+cm]               + q[r*16+cp]
                    + q[rp*16+cm] + q[rp*16+c] + q[rp*16+cp];
                case (cnt)
                    4'd2: next_q[r*16+c] = q[r*16+c];
                    4'd3: next_q[r*16+c] = 1'b1;
                    default: next_q[r*16+c] = 1'b0;
                endcase
            end
        end
    end

    always @(posedge clk) begin
        if (load)
            q <= data;
        else
            q <= next_q;
    end

endmodule

