module TopModule (
    input        clk,
    input        reset,
    input  [2:0] s,
    output       fr2,
    output       fr1,
    output       fr0,
    output       dfr
);

    reg [1:0] level;
    reg       dfr_r;
    reg [1:0] new_level;

    always @(*) begin
        if (s[2])
            new_level = 2'd3;
        else if (s[1])
            new_level = 2'd2;
        else if (s[0])
            new_level = 2'd1;
        else
            new_level = 2'd0;
    end

    always @(posedge clk) begin
        if (reset) begin
            level <= 2'd0;
            dfr_r <= 1'b1;
        end else begin
            level <= new_level;
            if (new_level == 2'd0)
                dfr_r <= 1'b1;
            else if (new_level == 2'd3)
                dfr_r <= 1'b0;
            else if (new_level < level)
                dfr_r <= 1'b1;
            else if (new_level > level)
                dfr_r <= 1'b0;
            else
                dfr_r <= dfr_r;
        end
    end

    assign fr0 = (level != 2'd3);
    assign fr1 = (level == 2'd0) || (level == 2'd1);
    assign fr2 = (level == 2'd0);
    assign dfr = dfr_r;

endmodule

