    input  bump_left,
    input  bump_right,
    input  ground,
    input  dig,
    output walk_left,
    output walk_right,
    output aaah,
    output digging
);

    localparam WL    = 3'd0,
               WR    = 3'd1,
               FL    = 3'd2,
               FR    = 3'd3,
               DL    = 3'd4,
               DR    = 3'd5,
               SPLAT = 3'd6;

    reg [2:0] state, next_state;
    reg [4:0] count;

    always @(*) begin
        case (state)
            WL: begin
                if (!ground)        next_state = FL;
                else if (dig)       next_state = DL;
                else if (bump_left) next_state = WR;
                else                next_state = WL;
            end
            WR: begin
                if (!ground)         next_state = FR;
                else if (dig)        next_state = DR;
                else if (bump_right) next_state = WL;
                else                 next_state = WR;
            end
            FL: begin
                if (ground) next_state = (count > 5'd19) ? SPLAT : WL;
                else        next_state = FL;
            end
            FR: begin
                if (ground) next_state = (count > 5'd19) ? SPLAT : WR;
                else        next_state = FR;
            end
            DL:    next_state = ground ? DL : FL;
            DR:    next_state = ground ? DR : FR;
            SPLAT: next_state = SPLAT;
            default: next_state = WL;
        endcase
    end

    always @(posedge clk or posedge areset) begin
        if (areset)
            state <= WL;
        else
            state <= next_state;
    end

    always @(posedge clk or posedge areset) begin
        if (areset)
            count <= 5'd0;
        else if (state == FL || state == FR) begin
            if (count != 5'd31)
                count <= count + 5'd1;
        end
        else
            count <= 5'd0;
