module TopModule (
    input  wire       clk,
    input  wire       reset,
    input  wire       data,
    output wire [3:0] count,
    output wire       counting,
    output wire       done,
    input  wire       ack
);

    localparam [3:0] S    = 4'd0,
                     S1   = 4'd1,
                     S11  = 4'd2,
                     S110 = 4'd3,
                     B0   = 4'd4,
                     B1   = 4'd5,
                     B2   = 4'd6,
                     B3   = 4'd7,
                     CNT  = 4'd8,
                     WT   = 4'd9;

    reg [3:0] state, next_state;
    reg [3:0] cnt;
    reg [9:0] cyc;

    // Next-state logic
    always @(*) begin
        case (state)
            S:    next_state = data ? S1   : S;
            S1:   next_state = data ? S11  : S;
            S11:  next_state = data ? S11  : S110;
            S110: next_state = data ? B0   : S;
            B0:   next_state = B1;
            B1:   next_state = B2;
            B2:   next_state = B3;
            B3:   next_state = CNT;
            CNT:  next_state = ((cnt == 4'd0) && (cyc == 10'd999)) ? WT : CNT;
            WT:   next_state = ack ? S : WT;
            default: next_state = S;
        endcase
    end

    // State register
    always @(posedge clk) begin
        if (reset)
            state <= S;
        else
            state <= next_state;
    end

    // Datapath: delay shift register / down counter and cycle counter
    always @(posedge clk) begin
        if (reset) begin
            cnt <= 4'd0;
            cyc <= 10'd0;
        end else begin
            case (state)
                B0, B1, B2, B3: begin
                    cnt <= {cnt[2:0], data};
                    cyc <= 10'd0;
                end
                CNT: begin
                    if (cyc == 10'd999) begin
                        cyc <= 10'd0;
                        cnt <= cnt - 4'd1;
                    end else begin
                        cyc <= cyc + 10'd1;
                    end
                end
                default: begin
                    cyc <= 10'd0;
                end
            endcase
        end
    end

    assign count    = cnt;
    assign counting = (state == CNT);
    assign done     = (state == WT);

endmodule

