module TopModule (
    input  clk,
    input  areset,
    input  x,
    output z
);

    // One-hot state encoding: sA = state A, sB = state B
    reg sA, sB;

    // Next-state logic
    wire nA = sA & ~x;
    wire nB = (sA & x) | sB;

    // Sequential logic: asynchronous active-high reset to state A
    always @(posedge clk or posedge areset) begin
        if (areset) begin
            sA <= 1'b1;
            sB <= 1'b0;
        end else begin
            sA <= nA;
            sB <= nB;
        end
    end

    // Mealy output logic
    assign z = (sA & x) | (sB & ~x);

endmodule

