module TopModule (
    input  clk,
    input  reset,
    input  data,
    output start_shifting
);

    localparam S0 = 3'd0;  // No relevant prefix matched
    localparam S1 = 3'd1;  // Seen "1"
    localparam S2 = 3'd2;  // Seen "11"
    localparam S3 = 3'd3;  // Seen "110"
    localparam S4 = 3'd4;  // Seen "1101" (absorbing)

    reg [2:0] state, next_state;

    // State register with synchronous active-high reset
    always @(posedge clk) begin
        if (reset)
            state <= S0;
        else
            state <= next_state;
    end

    // Next-state logic
    always @(*) begin
        case (state)
            S0: next_state = data ? S1 : S0;
            S1: next_state = data ? S2 : S0;
            S2: next_state = data ? S2 : S3;
            S3: next_state = data ? S4 : S0;
            S4: next_state = S4;
            default: next_state = S0;
        endcase
    end

    // Output is high once the sequence has been found, until reset
    assign start_shifting = (state == S4);

endmodule

