module TopModule (
    input  clk,
    input  reset,
    input  w,
    output z
);

    localparam [2:0] A = 3'd0,
                     B = 3'd1,
                     C = 3'd2,
                     D = 3'd3,
                     E = 3'd4,
                     F = 3'd5;

    reg [2:0] present_state;
    reg [2:0] next_state;

