module TopModule (
    input  in,
    input  [9:0] state,
    output [9:0] next_state,
    output out1,
    output out2
);

    // next_state[0]: S0 is reached on input 0 from S0, S1, S2, S3, S4, S7, S8, S9
    assign next_state[0] = ~in & (state[0] | state[1] | state[2] | state[3] | state[4] |
                                  state[7] | state[8] | state[9]);

    // next_state[1]: S1 is reached on input 1 from S0, S8, S9
    assign next_state[1] = in & (state[0] | state[8] | state[9]);

    // next_state[2]: S2 is reached on input 1 from S1
    assign next_state[2] = in & state[1];

    // next_state[3]: S3 is reached on input 1 from S2
    assign next_state[3] = in & state[2];

    // next_state[4]: S4 is reached on input 1 from S3
    assign next_state[4] = in & state[3];

    // next_state[5]: S5 is reached on input 1 from S4
    assign next_state[5] = in & state[4];

    // next_state[6]: S6 is reached on input 1 from S5
    assign next_state[6] = in & state[5];

    // next_state[7]: S7 is reached on input 1 from S6 or S7
    assign next_state[7] = in & (state[6] | state[7]);

    // next_state[8]: S8 is reached on input 0 from S5
    assign next_state[8] = ~in & state[5];

    // next_state[9]: S9 is reached on input 0 from S6
    assign next_state[9] = ~in & state[6];

    // Moore outputs: out1 in S8, S9; out2 in S7, S9
    assign out1 = state[8] | state[9];
    assign out2 = state[7] | state[9];

