module TopModule (
    input  wire       clk,
    input  wire       reset,
    input  wire       ena,
    output reg        pm,
    output reg [7:0]  hh,
    output reg [7:0]  mm,
    output reg [7:0]  ss
);

    always @(posedge clk) begin
        if (reset) begin
            hh <= 8'h12;
            mm <= 8'h00;
            ss <= 8'h00;
            pm <= 1'b0;
        end else if (ena) begin
            // Seconds: 00-59 BCD
            if (ss == 8'h59)
                ss <= 8'h00;
            else if (ss[3:0] == 4'd9)
                ss <= {ss[7:4] + 4'd1, 4'd0};
            else
                ss <= ss + 8'd1;

            // Minutes: 00-59 BCD, increment when seconds roll over
            if (ss == 8'h59) begin
                if (mm == 8'h59)
                    mm <= 8'h00;
                else if (mm[3:0] == 4'd9)
                    mm <= {mm[7:4] + 4'd1, 4'd0};
                else
                    mm <= mm + 8'd1;
            end

            // Hours: 01-12 BCD, increment when minutes and seconds roll over
            if (ss == 8'h59 && mm == 8'h59) begin
                if (hh == 8'h12)
                    hh <= 8'h01;
                else if (hh[3:0] == 4'd9)
                    hh <= {hh[7:4] + 4'd1, 4'd0};
                else
                    hh <= hh + 8'd1;

                // Toggle AM/PM when going from 11:59:59 to 12:00:00
                if (hh == 8'h11)
                    pm <= ~pm;
            end
        end
    end

endmodule

