module TopModule (
    input  clk,
    input  reset,
    input  in,
    output reg done
);

    localparam IDLE = 2'd0;  // Waiting for start bit (0)
    localparam DATA = 2'd1;  // Receiving 8 data bits (LSB first)
    localparam STOP = 2'd2;  // Checking stop bit (1)
    localparam ERR  = 2'd3;  // Stop bit missing: wait for line to return to 1

    reg [1:0] state;
    reg [2:0] cnt;

    always @(posedge clk) begin
        if (reset) begin
            state <= IDLE;
            cnt   <= 3'd0;
            done  <= 1'b0;
        end else begin
            done <= 1'b0;

            case (state)
                IDLE: begin
                    if (in == 1'b0) begin
                        state <= DATA;
                        cnt   <= 3'd0;
                    end
                end

                DATA: begin
                    cnt <= cnt + 3'd1;
                    if (cnt == 3'd7)
                        state <= STOP;
                end

                STOP: begin
                    if (in == 1'b1) begin
                        done  <= 1'b1;   // Valid byte received
                        state <= IDLE;
                    end else begin
                        state <= ERR;    // Bad stop bit
                    end
                end

                ERR: begin
                    if (in == 1'b1)
                        state <= IDLE;   // Resynchronize on stop/idle line
                end

                default: state <= IDLE;
            endcase
        end
    end

endmodule

