      ERR:     next_state = in ? ERR  : S0;
      default: next_state = S0;
    endcase
  end

  // Moore outputs (depend only on current state)
  assign disc = (state == DISC);
  assign flag = (state == FLAG);
  assign err  = (state == ERR);

