module TopModule (
    input  clk,
    input  in,
    input  reset,
    output [7:0] out_byte,
    output done
);

    localparam IDLE = 2'd0;
    localparam DATA = 2'd1;
    localparam STOP = 2'd2;
    localparam ERR  = 2'd3;

    reg [1:0] state;
    reg [2:0] count;
    reg [7:0] shift;

    always @(posedge clk) begin
        if (reset) begin
            state <= IDLE;
            count <= 3'd0;
            shift <= 8'd0;
        end else begin
            case (state)
                IDLE: begin
                    if (!in) begin
                        state <= DATA;
                        count <= 3'd0;
                    end
                end
                DATA: begin
                    shift <= {in, shift[7:1]};
                    count <= count + 3'd1;
                    if (count == 3'd7)
                        state <= STOP;
                end
                STOP: begin
                    if (in)
                        state <= IDLE;
                    else
                        state <= ERR;
                end
                ERR: begin
                    if (in)
                        state <= IDLE;
                end
                default: state <= IDLE;
            endcase
        end
    end

    assign out_byte = shift;
    assign done = (state == STOP) && in;

endmodule

