module TopModule (
    input  clk,
    input  reset,
    input  data,
    input  done_counting,
    input  ack,
    output shift_ena,
    output counting,
    output done
);

    localparam IDLE  = 3'd0,
               S1    = 3'd1,
               S11   = 3'd2,
               S110  = 3'd3,
               SHIFT = 3'd4,
               COUNT = 3'd5,
               DONE  = 3'd6;

    reg [2:0] state;
    reg [2:0] next_state;
    reg [1:0] shift_cnt;

    // State register with active-high synchronous reset
    always @(posedge clk) begin
        if (reset)
            state <= IDLE;
        else
            state <= next_state;
    end

    // Shift counter: counts 4 cycles in SHIFT state
    always @(posedge clk) begin
        if (reset)
            shift_cnt <= 2'd0;
        else if (state == SHIFT)
            shift_cnt <= shift_cnt + 2'd1;
        else
            shift_cnt <= 2'd0;
    end

    // Next-state logic
    always @(*) begin
        next_state = state;
        case (state)
            IDLE:    next_state = data ? S1 : IDLE;
            S1:      next_state = data ? S11 : IDLE;
            S11:     next_state = data ? S11 : S110;
            S110:    next_state = data ? SHIFT : IDLE;
            SHIFT:   next_state = (shift_cnt == 2'd3) ? COUNT : SHIFT;
            COUNT:   next_state = done_counting ? DONE : COUNT;
            DONE:    next_state = ack ? IDLE : DONE;
            default: next_state = IDLE;
        endcase
    end

    // Output logic
    assign shift_ena = (state == SHIFT);
    assign counting  = (state == COUNT);
    assign done      = (state == DONE);

endmodule

