module TopModule (
    input  clk,
    input  reset,
    input  s,
    input  w,
    output z
);

    localparam [2:0] A   = 3'd0,  // idle, waiting for s = 1
                     B   = 3'd1,  // window start, 0 ones so far, previous z = 0
                     Q0  = 3'd2,  // 1 sample taken, 0 ones so far
                     Q1  = 3'd3,  // 1 sample taken, 1 one so far
                     D   = 3'd4,  // window cannot reach exactly 2 ones
                     R1  = 3'd5,  // 2 samples taken, 1 one so far
                     R2  = 3'd6,  // 2 samples taken, 2 ones so far
                     BZ  = 3'd7;  // window start, previous window had 2 ones (z = 1)

    reg [2:0] state, next_state;

    always @(*) begin
        case (state)
            A:       next_state = s ? B : A;
            B:       next_state = w ? Q1 : Q0;
            BZ:      next_state = w ? Q1 : Q0;
            Q0:      next_state = w ? R1 : D;
            Q1:      next_state = w ? R2 : R1;
            D:       next_state = B;
            R1:      next_state = w ? BZ : B;
            R2:      next_state = w ? B : BZ;
            default: next_state = A;
        endcase
    end

    always @(posedge clk) begin
        if (reset)
            state <= A;
        else
            state <= next_state;
    end

    assign z = (state == BZ);

