module TopModule (
    input  clk,
    input  reset,
    input  [2:0] s,
    output fr2,
    output fr1,
    output fr0,
    output dfr
);

    reg [2:0] lvl;   // last sensor reading (FSM level state)
    reg       up;    // 1 if the most recent sensor change was a rise

    always @(posedge clk) begin
        if (reset) begin
            lvl <= 3'b000;
            up  <= 1'b1;
