            lvl <= s;
            up  <= (s > lvl);
        end
    end

    assign fr0 = ~(&lvl);
    assign fr1 = ~lvl[1];
    assign fr2 = ~lvl[0];
    assign dfr = up | ~lvl[0];

endmodule

