module TopModule (
    input  clk,
    input  areset,
    input  bump_left,
    input  bump_right,
    input  ground,
    input  dig,
    output walk_left,
    output walk_right,
    output aaah,
    output digging
);

    localparam [2:0] WL = 3'd0,  // walking left
                     WR = 3'd1,  // walking right
                     FL = 3'd2,  // falling, will resume walking left
                     FR = 3'd3,  // falling, will resume walking right
                     DL = 3'd4,  // digging, moving left
                     DR = 3'd5;  // digging, moving right

    reg [2:0] state, next_state;

    // State register with asynchronous active-high reset to walk left
    always @(posedge clk or posedge areset) begin
        if (areset)
            state <= WL;
        else
            state <= next_state;
    end

    // Next-state logic
    always @(*) begin
        case (state)
            WL: begin
                if (!ground)          next_state = FL;  // fall has highest precedence
                else if (dig)         next_state = DL;  // dig before direction change
                else if (bump_left)   next_state = WR;  // bumped on left -> walk right
                else                  next_state = WL;
            end
            WR: begin
                if (!ground)          next_state = FR;
                else if (dig)         next_state = DR;
                else if (bump_right)  next_state = WL;  // bumped on right -> walk left
                else                  next_state = WR;
            end
            FL: begin
                if (ground)           next_state = WL;  // resume walking left
                else                  next_state = FL;  // bumps and dig ignored
            end
            FR: begin
                if (ground)           next_state = WR;  // resume walking right
                else                  next_state = FR;
            end
            DL: begin
                if (!ground)          next_state = FL;  // reached edge, fall
                else                  next_state = DL;  // keep digging, bumps ignored
            end
            DR: begin
                if (!ground)          next_state = FR;
                else                  next_state = DR;
            end
            default:                  next_state = WL;
        endcase
    end

    // Moore outputs depend only on the current state
    assign walk_left  = (state == WL);
    assign walk_right = (state == WR);
    assign aaah       = (state == FL) || (state == FR);
    assign digging    = (state == DL) || (state == DR);

