module TopModule (
  input        clk,
  input        reset,
  input  [7:0] in,
  output [23:0] out_bytes,
  output       done
);

  reg [1:0]  state;
  reg [23:0] bytes_r;
  reg        done_r;

  always @(posedge clk) begin
    if (reset) begin
      state   <= 2'd0;
      bytes_r <= 24'd0;
      done_r  <= 1'b0;
    end else begin
      done_r <= 1'b0;
      case (state)
        2'd0: begin
          if (in[3]) begin
            bytes_r[23:16] <= in;
            state          <= 2'd1;
          end
        end
        2'd1: begin
          bytes_r[15:8] <= in;
          state         <= 2'd2;
        end
        2'd2: begin
          bytes_r[7:0] <= in;
          state        <= 2'd0;
          done_r       <= 1'b1;
        end
        default: state <= 2'd0;
      endcase
    end
  end

  assign out_bytes = bytes_r;
  assign done      = done_r;

endmodule

