module TopModule (
    input  clk,
    input  areset,
    input  x,
    output z
);

    reg [1:0] state, next_state;

    localparam A = 0;
    localparam B = 1;

    // State transition logic (one-hot)
    always @(*) begin
        next_state = 2'b00;
        if (state[A]) begin
            if (x) next_state[B] = 1'b1;
            else   next_state[A] = 1'b1;
        end
        if (state[B]) begin
            next_state[B] = 1'b1;
        end
    end

    // State register with asynchronous active-high reset
    always @(posedge clk or posedge areset) begin
        if (areset)
            state <= 2'b01;
        else
            state <= next_state;
    end

    // Mealy output
    assign z = (state[A] & x) | (state[B] & ~x);

endmodule

