module TopModule (
    input  clk,
    input  reset,
    input  in,
    output done
);

    localparam IDLE  = 2'd0;
    localparam DATA  = 2'd1;
    localparam STOP  = 2'd2;
    localparam WAIT  = 2'd3;

    reg [1:0] state, next_state;
    reg [3:0] cnt;

    always @(*) begin
        next_state = state;
        case (state)
            IDLE: begin
                if (in == 1'b0)
                    next_state = DATA;
            end
            DATA: begin
                if (cnt == 4'd7)
                    next_state = STOP;
            end
            STOP: begin
                if (in == 1'b1)
                    next_state = IDLE;
                else
                    next_state = WAIT;
            end
            WAIT: begin
                if (in == 1'b1)
                    next_state = IDLE;
            end
            default: next_state = IDLE;
        endcase
    end

    always @(posedge clk) begin
        if (reset) begin
            state <= IDLE;
            cnt   <= 4'd0;
        end else begin
            state <= next_state;
            if (state == DATA)
                cnt <= (cnt == 4'd7) ? 4'd0 : cnt + 4'd1;
            else
                cnt <= 4'd0;
        end
    end

    assign done = (state == STOP) && (in == 1'b1);

endmodule

