module TopModule (
    input        clk,
    input        reset,
    input  [2:0] s,
    output       fr2,
    output       fr1,
    output       fr0,
    output       dfr
);

    reg [1:0] lvl;      // registered (previous) level: 0 = below s0, 3 = above s2
    reg       up;       // 1 if last level change was upward
    reg [1:0] newlvl;

    always @(*) begin
        case (s)
            3'b111:  newlvl = 2'd3;
            3'b011:  newlvl = 2'd2;
            3'b001:  newlvl = 2'd1;
            default: newlvl = 2'd0;
        endcase
    end

    always @(posedge clk) begin
        if (reset) begin
            lvl <= 2'd0;
            up  <= 1'b1;
        end else begin
            lvl <= newlvl;
            if (newlvl > lvl)
