module TopModule (
    input  clk,
    input  reset,
    input  data,
    output [3:0] count,
    output counting,
    output done,
    input  ack
);

    localparam S0    = 4'd0;
    localparam S1    = 4'd1;
    localparam S11   = 4'd2;
    localparam S110  = 4'd3;
    localparam SH0   = 4'd4;
    localparam SH1   = 4'd5;
    localparam SH2   = 4'd6;
    localparam SH3   = 4'd7;
    localparam CNT   = 4'd8;
    localparam DONE  = 4'd9;

    reg [3:0] state;
    reg [3:0] delay;
    reg [9:0] cyc;

    assign count    = delay;
    assign counting = (state == CNT);
    assign done     = (state == DONE);

    always @(posedge clk) begin
        if (reset) begin
            state <= S0;
            delay <= 4'd0;
            cyc   <= 10'd0;
        end else begin
            case (state)
                S0:   state <= data ? S1 : S0;
                S1:   state <= data ? S11 : S0;
                S11:  state <= data ? S11 : S110;
                S110: state <= data ? SH0 : S0;
                SH0: begin
                    delay <= {delay[2:0], data};
                    state <= SH1;
                end
                SH1: begin
                    delay <= {delay[2:0], data};
                    state <= SH2;
                end
                SH2: begin
                    delay <= {delay[2:0], data};
                    state <= SH3;
                end
                SH3: begin
                    delay <= {delay[2:0], data};
                    cyc   <= 10'd0;
                    state <= CNT;
                end
                CNT: begin
                    if (cyc == 10'd999) begin
                        cyc <= 10'd0;
                        if (delay == 4'd0) begin
                            state <= DONE;
                        end else begin
                            delay <= delay - 4'd1;
                        end
                    end else begin
                        cyc <= cyc + 10'd1;
                    end
                end
                DONE: begin
                    if (ack)
                        state <= S0;
                end
                default: state <= S0;
            endcase
        end
    end

endmodule

