module TopModule (
    input  clk,
    input  reset,
    input  s,
    input  w,
    output reg z
);

    localparam A = 1'b0;
    localparam B = 1'b1;

    reg       state;
    reg [1:0] cnt;
    reg [1:0] ones;

    always @(posedge clk) begin
        if (reset) begin
            state <= A;
            cnt   <= 2'd0;
            ones  <= 2'd0;
            z     <= 1'b0;
        end
        else begin
            case (state)
                A: begin
                    z    <= 1'b0;
                    cnt  <= 2'd0;
                    ones <= 2'd0;
                    if (s)
                        state <= B;
                    else
                        state <= A;
                end
                B: begin
                    if (cnt == 2'd2) begin
                        z    <= ((ones + {1'b0, w}) == 2'd2);
                        cnt  <= 2'd0;
                        ones <= 2'd0;
                    end
                    else begin
                        z    <= 1'b0;
                        cnt  <= cnt + 2'd1;
                        ones <= ones + {1'b0, w};
                    end
                    state <= B;
                end
                default: begin
                    state <= A;
                    cnt   <= 2'd0;
                    ones  <= 2'd0;
                    z     <= 1'b0;
                end
            endcase
        end
    end

endmodule

