    input  clk,
    input  reset,
    input  in,
    output done
);

    localparam IDLE = 3'd0,
               DATA = 3'd1,
               STOP = 3'd2,
               DONE = 3'd3,
               ERR  = 3'd4;

    reg [2:0] state, next_state;
    reg [3:0] cnt;

    always @(*) begin
        next_state = state;
        case (state)
            IDLE: next_state = in ? IDLE : DATA;
            DATA: next_state = (cnt == 4'd7) ? STOP : DATA;
            STOP: next_state = in ? DONE : ERR;
            DONE: next_state = in ? IDLE : DATA;
            ERR:  next_state = in ? IDLE : ERR;
            default: next_state = IDLE;
        endcase
    end

    always @(posedge clk) begin
        if (reset) begin
            state <= IDLE;
            cnt   <= 4'd0;
        end else begin
            state <= next_state;
            if (state == DATA)
                cnt <= cnt + 4'd1;
            else
                cnt <= 4'd0;
        end
    end

    assign done = (state == DONE);

endmodule

