module TopModule (
  input  clk,
  input  resetn,
  input  x,
  input  y,
  output f,
  output g
);

  localparam [3:0] S_A    = 4'd0,
                   S_F1   = 4'd1,
                   S_IDLE = 4'd2,
                   S_X1   = 4'd3,
                   S_X10  = 4'd4,
                   S_G1   = 4'd5,
                   S_G2   = 4'd6,
                   S_GON  = 4'd7,
                   S_GOFF = 4'd8;

  reg [3:0] state, next_state;

  always @(*) begin
    case (state)
      S_A:    next_state = S_F1;
      S_F1:   next_state = S_IDLE;
      S_IDLE: next_state = x ? S_X1   : S_IDLE;
      S_X1:   next_state = x ? S_X1   : S_X10;
      S_X10:  next_state = x ? S_G1   : S_IDLE;
      S_G1:   next_state = y ? S_GON  : S_G2;
      S_G2:   next_state = y ? S_GON  : S_GOFF;
      S_GON:  next_state = S_GON;
      S_GOFF: next_state = S_GOFF;
      default: next_state = S_A;
    endcase
  end

  always @(posedge clk) begin
    if (!resetn)
      state <= S_A;
    else
      state <= next_state;
  end

  assign f = (state == S_F1);
  assign g = (state == S_G1) || (state == S_G2) || (state == S_GON);

endmodule

