module TopModule (
    input  wire       clk,
    input  wire       reset,
    input  wire       data,
    output wire [3:0] count,
    output wire       counting,
    output wire       done,
    input  wire       ack
);

    localparam S     = 4'd0,
               S1    = 4'd1,
               S11   = 4'd2,
               S110  = 4'd3,
               B0    = 4'd4,
               B1    = 4'd5,
               B2    = 4'd6,
               B3    = 4'd7,
               COUNT = 4'd8,
               WAIT  = 4'd9;

    reg [3:0] state, next_state;
    reg [3:0] delay;
    reg [9:0] cnt;

    wire last_cycle = (cnt == 10'd999) && (delay == 4'd0);

    always @(*) begin
        case (state)
            S:     next_state = data ? S1 : S;
            S1:    next_state = data ? S11 : S;
            S11:   next_state = data ? S11 : S110;
            S110:  next_state = data ? B0 : S;
            B0:    next_state = B1;
            B1:    next_state = B2;
            B2:    next_state = B3;
            B3:    next_state = COUNT;
            COUNT: next_state = last_cycle ? WAIT : COUNT;
            WAIT:  next_state = ack ? S : WAIT;
            default: next_state = S;
        endcase
    end

    always @(posedge clk) begin
        if (reset)
            state <= S;
        else
            state <= next_state;
    end

    always @(posedge clk) begin
        if (reset) begin
            delay <= 4'd0;
            cnt   <= 10'd0;
        end else begin
            case (state)
                B0, B1, B2, B3: begin
                    delay <= {delay[2:0], data};
                    cnt   <= 10'd0;
                end
                COUNT: begin
                    if (cnt == 10'd999) begin
                        cnt <= 10'd0;
                        if (delay != 4'd0)
                            delay <= delay - 4'd1;
                    end else begin
                        cnt <= cnt + 10'd1;
                    end
                end
                default: begin
                    cnt <= 10'd0;
                end
            endcase
        end
    end

    assign count    = delay;
    assign counting = (state == COUNT);
    assign done     = (state == WAIT);

endmodule

