module TopModule (
    input  in,
    input  [3:0] state,
    output [3:0] next_state,
    output out
);

    // One-hot encoding: A = state[0], B = state[1], C = state[2], D = state[3]

    // next_state[0] (A): from A and C when in = 0
    assign next_state[0] = ~in & (state[0] | state[2]);

    // next_state[1] (B): from A, B, and D when in = 1
    assign next_state[1] = in & (state[0] | state[1] | state[3]);

    // next_state[2] (C): from B and D when in = 0
    assign next_state[2] = ~in & (state[1] | state[3]);

    // next_state[3] (D): from C when in = 1
    assign next_state[3] = in & state[2];

    // Moore output: 1 only in state D
    assign out = state[3];

endmodule

