module TopModule (
    input  clk,
    input  areset,
    input  x,
    output z
);

    // One-hot state encoding: stateA and stateB, exactly one is high
    reg stateA, stateB;

    // Next-state logic
    wire nextA = stateA & ~x;
    wire nextB = (stateA & x) | stateB;

    // Mealy output logic
    assign z = (stateA & x) | (stateB & ~x);

    // State register with asynchronous active-high reset into state A
    always @(posedge clk or posedge areset) begin
        if (areset) begin
            stateA <= 1'b1;
            stateB <= 1'b0;
        end else begin
            stateA <= nextA;
            stateB <= nextB;
        end
    end

endmodule

