    input  reset,
    input  data,
    output start_shifting
);

    localparam S0 = 3'd0; // no matching prefix
    localparam S1 = 3'd1; // seen "1"
    localparam S2 = 3'd2; // seen "11"
    localparam S3 = 3'd3; // seen "110"
    localparam S4 = 3'd4; // seen "1101" (sticky)

    reg [2:0] state, next_state;

    always @(*) begin
        case (state)
            S0: next_state = data ? S1 : S0;
            S1: next_state = data ? S2 : S0;
