  input  reset,
  input  x,
  output z
);

  reg [2:0] y;
  reg [2:0] y_next;

  // State register with synchronous active-high reset to 000
  always @(posedge clk) begin
    if (reset)
      y <= 3'b000;
    else
      y <= y_next;
