module TopModule (
    input  clk,
    input  areset,
    input  bump_left,
    input  bump_right,
    input  ground,
    output walk_left,
    output walk_right,
    output aaah
);

    localparam [1:0] S_LEFT   = 2'd0,
                     S_RIGHT  = 2'd1,
                     S_FALL_L = 2'd2,
                     S_FALL_R = 2'd3;

    reg [1:0] state;
    reg [1:0] next_state;

    // State register with positive-edge asynchronous reset to walk left
    always @(posedge clk or posedge areset) begin
        if (areset)
            state <= S_LEFT;
        else
            state <= next_state;
    end

    // Next-state logic
    always @(*) begin
        case (state)
            S_LEFT: begin
                if (!ground)
                    next_state = S_FALL_L;
                else if (bump_left)
                    next_state = S_RIGHT;
                else
                    next_state = S_LEFT;
            end

            S_RIGHT: begin
                if (!ground)
                    next_state = S_FALL_R;
                else if (bump_right)
                    next_state = S_LEFT;
                else
                    next_state = S_RIGHT;
            end

            S_FALL_L: begin
                if (ground)
                    next_state = S_LEFT;
                else
                    next_state = S_FALL_L;
            end

            S_FALL_R: begin
                if (ground)
                    next_state = S_RIGHT;
                else
                    next_state = S_FALL_R;
            end

            default: next_state = S_LEFT;
        endcase
    end

    // Moore outputs depend only on the current state
    assign walk_left  = (state == S_LEFT);
    assign walk_right = (state == S_RIGHT);
    assign aaah       = (state == S_FALL_L) || (state == S_FALL_R);

endmodule

