                   SFLAG = 4'd8,  // 01111110 detected: frame flag
                   SERR  = 4'd9;  // 7 or more ones: error

  reg [3:0] state;
  reg [3:0] next_state;

  // State register (synchronous, active-high reset)
  always @(posedge clk) begin
    if (reset)
      state <= S0;
    else
      state <= next_state;
  end

  // Next-state logic
  always @(*) begin
    case (state)
      S0:    next_state = in ? S1    : S0;
      S1:    next_state = in ? S2    : S0;
      S2:    next_state = in ? S3    : S0;
