module TopModule (
    input  wire       clk,
    input  wire       reset,
    input  wire       ena,
    output reg        pm,
    output reg  [7:0] hh,
    output reg  [7:0] mm,
    output reg  [7:0] ss
);

    wire ss_lo_max = (ss[3:0] == 4'd9);
    wire ss_max    = ss_lo_max && (ss[7:4] == 4'd5);
    wire mm_lo_max = (mm[3:0] == 4'd9);
    wire mm_max    = mm_lo_max && (mm[7:4] == 4'd5);

    always @(posedge clk) begin
        if (reset) begin
            hh <= 8'h12;
            mm <= 8'h00;
            ss <= 8'h00;
            pm <= 1'b0;
        end else if (ena) begin
            // Seconds
            if (ss_max) begin
                ss <= 8'h00;
            end else if (ss_lo_max) begin
                ss[3:0] <= 4'd0;
                ss[7:4] <= ss[7:4] + 4'd1;
            end else begin
                ss[3:0] <= ss[3:0] + 4'd1;
            end

            // Minutes
            if (ss_max) begin
                if (mm_max) begin
                    mm <= 8'h00;
                end else if (mm_lo_max) begin
                    mm[3:0] <= 4'd0;
                    mm[7:4] <= mm[7:4] + 4'd1;
                end else begin
                    mm[3:0] <= mm[3:0] + 4'd1;
                end
            end

            // Hours (12-hour BCD, 01-12) with AM/PM toggle at 11 -> 12
            if (ss_max && mm_max) begin
                if (hh == 8'h12) begin
                    hh <= 8'h01;
                end else if (hh == 8'h11) begin
                    hh <= 8'h12;
                    pm <= ~pm;
                end else if (hh[3:0] == 4'd9) begin
                    hh <= 8'h10;
                end else begin
                    hh <= hh + 8'd1;
                end
            end
        end
    end

endmodule

