module TopModule (
    input  clk,
    input  reset,
    input  in,
    output done
);
    localparam [2:0] IDLE = 3'd0,
                     DATA = 3'd1,
                     STOP = 3'd2,
                     DONE = 3'd3,
                     ERR  = 3'd4;

    reg [2:0] state, next_state;
    reg [2:0] cnt;

    // State and bit counter registers (synchronous active-high reset)
    always @(posedge clk) begin
        if (reset) begin
            state <= IDLE;
            cnt   <= 3'd0;
        end else begin
            state <= next_state;
            if (state == DATA)
                cnt <= cnt + 3'd1;
            else
                cnt <= 3'd0;
        end
    end

    // Next-state logic
    always @(*) begin
        next_state = state;
        case (state)
            IDLE, DONE: next_state = in ? IDLE : DATA;      // start bit (0) begins a byte
            DATA:       if (cnt == 3'd7) next_state = STOP; // 8 data bits received, LSB first
            STOP:       next_state = in ? DONE : ERR;       // check stop bit (1)
            ERR:        if (in) next_state = IDLE;          // wait for line to return high
            default:    next_state = IDLE;
        endcase
    end

    // Byte successfully received when in DONE state
    assign done = (state == DONE);

endmodule

