    reg [2:0] cnt;

    // State and bit counter registers (synchronous active-high reset)
    always @(posedge clk) begin
        if (reset) begin
            state <= IDLE;
            cnt   <= 3'd0;
        end else begin
            state <= next_state;
            if (state == DATA)
                cnt <= cnt + 3'd1;
            else
                cnt <= 3'd0;
        end
    end

    // Next-state logic
    always @(*) begin
        next_state = state;
        case (state)
