module TopModule (
  input        clk,
  input        resetn,
  input  [2:0] r,
  output [2:0] g
);

  localparam [1:0] A = 2'd0,
                   B = 2'd1,
                   C = 2'd2,
                   D = 2'd3;

  reg [1:0] present_state, next_state;

  // State table (combinational next-state logic)
  always @(*) begin
    case (present_state)
      A: begin
        if (r[0])       next_state = B;
        else if (r[1])  next_state = C;
        else if (r[2])  next_state = D;
        else            next_state = A;
      end
      B: next_state = r[0] ? B : A;
      C: next_state = r[1] ? C : A;
      D: next_state = r[2] ? D : A;
      default: next_state = A;
    endcase
  end

  // State flip-flops (synchronous, active-low reset)
  always @(posedge clk) begin
    if (!resetn)
      present_state <= A;
    else
      present_state <= next_state;
  end

  // Output logic
  assign g[0] = (present_state == B);
  assign g[1] = (present_state == C);
  assign g[2] = (present_state == D);

endmodule

