module TopModule (
    input  clk,
    input  reset,
    input  data,
    input  done_counting,
    input  ack,
    output shift_ena,
    output counting,
    output done
);

    localparam [3:0] S        = 4'd0,   // searching for 1101
                     S1       = 4'd1,   // seen 1
                     S11      = 4'd2,   // seen 11
                     S110     = 4'd3,   // seen 110
                     B0       = 4'd4,   // shift in bit 0 of delay
                     B1       = 4'd5,   // shift in bit 1 of delay
                     B2       = 4'd6,   // shift in bit 2 of delay
                     B3       = 4'd7,   // shift in bit 3 of delay
                     COUNT    = 4'd8,   // wait for counters
                     WAITACK  = 4'd9;   // notify done, wait for ack

    reg [3:0] state, next_state;

    // Next-state logic
    always @(*) begin
        case (state)
            S:       next_state = data ? S1 : S;
            S1:      next_state = data ? S11 : S;
            S11:     next_state = data ? S11 : S110;
            S110:    next_state = data ? B0 : S;
            B0:      next_state = B1;
            B1:      next_state = B2;
            B2:      next_state = B3;
            B3:      next_state = COUNT;
            COUNT:   next_state = done_counting ? WAITACK : COUNT;
            WAITACK: next_state = ack ? S : WAITACK;
            default: next_state = S;
        endcase
    end

    // State register with active-high synchronous reset
    always @(posedge clk) begin
        if (reset)
            state <= S;
        else
            state <= next_state;
    end

    // Moore outputs
    assign shift_ena = (state == B0) || (state == B1) || (state == B2) || (state == B3);
    assign counting  = (state == COUNT);
    assign done      = (state == WAITACK);

