module TopModule (
    input  clk,
    input  reset,
    input  [2:0] s,
    output fr2,
    output fr1,
    output fr0,
    output dfr
);

    reg [2:0] s_q;      // sensor reading at previous clock
    reg       rise_q;   // 1 = level rose at last sensor change, 0 = fell
    reg [3:0] o;        // {fr2, fr1, fr0, dfr}

    wire [1:0] cnt_now  = s[0]   + s[1]   + s[2];
    wire [1:0] cnt_prev = s_q[0] + s_q[1] + s_q[2];

    // Direction of the most recent sensor change
    wire rise_eff = (cnt_now > cnt_prev) ? 1'b1 :
                    (cnt_now < cnt_prev) ? 1'b0 : rise_q;

    always @(posedge clk) begin
        if (reset) begin
            s_q    <= 3'b000;   // as if water had been low for a long time
            rise_q <= 1'b1;
        end else begin
            s_q    <= s;
            rise_q <= rise_eff;
        end
    end

    always @(*) begin
        case (s)
            3'b111:  o = 4'b0000;                 // above s[2]: no flow
            3'b011:  o = {1'b0, 1'b0, 1'b1, rise_eff}; // between s[2] and s[1]: fr0
            3'b001:  o = {1'b0, 1'b1, 1'b1, rise_eff}; // between s[1] and s[0]: fr0, fr1
            3'b000:  o = 4'b1111;                 // below s[0]: fr0, fr1, fr2, dfr
            default: o = 4'b0000;
        endcase
    end

    assign fr2 = o[3];
    assign fr1 = o[2];
    assign fr0 = o[1];
    assign dfr = o[0];

endmodule

