module TopModule (
    input  clk,
    input  reset,
    input  data,
    output [3:0] count,
    output counting,
    output done,
    input  ack
);

    localparam [2:0] P0    = 3'd0,  // searching, no prefix matched
                     P1    = 3'd1,  // matched "1"
                     P11   = 3'd2,  // matched "11"
                     P110  = 3'd3,  // matched "110"
                     SHIFT = 3'd4,  // shifting in delay[3:0], MSB first
                     COUNT = 3'd5,  // counting
                     DONE  = 3'd6;  // timed out, waiting for ack

    reg [2:0] state;
    reg [1:0] bitcnt;
    reg [2:0] sh;      // first 3 delay bits collected so far
    reg [3:0] cnt;     // remaining delay value (delay..0)
    reg [9:0] cyc;     // cycle counter within each 1000-cycle block

    assign count    = cnt;
    assign counting = (state == COUNT);
    assign done     = (state == DONE);

    always @(posedge clk) begin
        if (reset) begin
            state  <= P0;
            bitcnt <= 2'd0;
            sh     <= 3'd0;
            cnt    <= 4'd0;
            cyc    <= 10'd0;
        end else begin
            case (state)
                P0: begin
                    state <= data ? P1 : P0;
                end

                P1: begin
                    state <= data ? P11 : P0;
                end

                P11: begin
                    state <= data ? P11 : P110;
                end

                P110: begin
                    if (data) begin
                        state  <= SHIFT;
                        bitcnt <= 2'd0;
                    end else begin
                        state <= P0;
                    end
                end

                SHIFT: begin
                    sh     <= {sh[1:0], data};
                    bitcnt <= bitcnt + 2'd1;
                    if (bitcnt == 2'd3) begin
                        cnt   <= {sh, data};
                        cyc   <= 10'd0;
                        state <= COUNT;
                    end
                end

                COUNT: begin
                    if (cyc == 10'd999) begin
                        cyc <= 10'd0;
                        if (cnt == 4'd0)
                            state <= DONE;
                        else
                            cnt <= cnt - 4'd1;
                    end else begin
                        cyc <= cyc + 10'd1;
                    end
                end

                DONE: begin
                    if (ack)
                        state <= P0;
                end

                default: state <= P0;
            endcase
        end
    end

endmodule

