module TopModule (
    input  clk,
    input  d,
    output q
);

    reg p;  // captures d on posedge
    reg n;  // captures d on negedge

    always @(posedge clk) begin
        p <= d;
    end

    always @(negedge clk) begin
        n <= d;
    end

    // When clk is high, the most recent edge was posedge -> output p
    // When clk is low, the most recent edge was negedge -> output n
    assign q = clk ? p : n;

endmodule

