module TopModule (
    input  clk,
    input  reset,
    output shift_ena
);

    reg [2:0] count;
    reg       done;

    always @(posedge clk) begin
        if (reset) begin
            count <= 3'd0;
            done  <= 1'b0;
        end else begin
            if (!done) begin
                if (count == 3'd3) begin
                    done  <= 1'b1;
                    count <= count;
                end else begin
                    count <= count + 3'd1;
                end
            end
        end
    end

    assign shift_ena = ~done;

endmodule

