module TopModule (
    input  clk,
    input  areset,
    input  bump_left,
    input  bump_right,
    input  ground,
    output walk_left,
    output walk_right,
    output aaah
);

    localparam WL = 2'd0,
               WR = 2'd1,
               FL = 2'd2,
               FR = 2'd3;

    reg [1:0] state, next;

    always @(*) begin
        case (state)
            WL: begin
                if (!ground)         next = FL;
                else if (bump_left)  next = WR;
                else                 next = WL;
            end
            WR: begin
                if (!ground)         next = FR;
                else if (bump_right) next = WL;
                else                 next = WR;
            end
            FL: begin
                if (ground) next = WL;
                else        next = FL;
            end
            FR: begin
                if (ground) next = WR;
                else        next = FR;
            end
            default: next = WL;
        endcase
    end

    always @(posedge clk or posedge areset) begin
        if (areset)
            state <= WL;
        else
            state <= next;
    end

    assign walk_left  = (state == WL);
    assign walk_right = (state == WR);
    assign aaah       = (state == FL) || (state == FR);

endmodule

