module TopModule (
    input clk,
    input in,
    input reset,
    output [7:0] out_byte,
    output done
);

    localparam IDLE  = 3'd0;
    localparam DATA  = 3'd1;
    localparam STOP  = 3'd2;
    localparam WAIT  = 3'd3;

    reg [2:0] state, next_state;
    reg [2:0] count;
    reg [7:0] shift;
    reg [7:0] data_reg;

    always @(*) begin
        next_state = state;
        case (state)
            IDLE: begin
                if (!in) next_state = DATA;
            end
            DATA: begin
                if (count == 3'd7) next_state = STOP;
            end
            STOP: begin
                if (in) next_state = IDLE;
                else    next_state = WAIT;
            end
            WAIT: begin
                if (in) next_state = IDLE;
            end
            default: next_state = IDLE;
        endcase
    end

    always @(posedge clk) begin
        if (reset) begin
            state <= IDLE;
            count <= 3'd0;
            shift <= 8'd0;
            data_reg <= 8'd0;
        end else begin
            state <= next_state;
            case (state)
                IDLE: begin
                    count <= 3'd0;
                end
                DATA: begin
                    shift <= {in, shift[7:1]};
                    count <= count + 3'd1;
                end
                STOP: begin
                    if (in) data_reg <= shift;
                end
                default: ;
            endcase
        end
    end

    assign done = (state == STOP) && in;
    assign out_byte = data_reg;

endmodule

