module TopModule (
    input  clk,
    input  reset,
    input  data,
    input  done_counting,
    input  ack,
    output shift_ena,
    output counting,
    output done
);

    localparam S0    = 4'd0;
    localparam S1    = 4'd1;
    localparam S11   = 4'd2;
    localparam S110  = 4'd3;
    localparam B0    = 4'd4;
    localparam B1    = 4'd5;
    localparam B2    = 4'd6;
    localparam B3    = 4'd7;
    localparam CNT   = 4'd8;
    localparam DONE  = 4'd9;

    reg [3:0] state, next;

    always @(*) begin
        case (state)
            S0:   next = data ? S1 : S0;
            S1:   next = data ? S11 : S0;
            S11:  next = data ? S11 : S110;
            S110: next = data ? B0 : S0;
            B0:   next = B1;
            B1:   next = B2;
            B2:   next = B3;
            B3:   next = CNT;
            CNT:  next = done_counting ? DONE : CNT;
            DONE: next = ack ? S0 : DONE;
            default: next = S0;
        endcase
    end

    always @(posedge clk) begin
        if (reset)
            state <= S0;
        else
            state <= next;
    end

    assign shift_ena = (state == B0) || (state == B1) || (state == B2) || (state == B3);
    assign counting  = (state == CNT);
    assign done      = (state == DONE);

endmodule

