module TopModule (
    input  clk,
    input  reset,
    input  [2:0] s,
    output reg fr2,
    output reg fr1,
    output reg fr0,
    output reg dfr
);

    reg [1:0] level;
    reg       dfr_r;
    reg [1:0] new_level;

    always @(*) begin
        case (s)
            3'b111:  new_level = 2'd3;
            3'b011:  new_level = 2'd2;
            3'b001:  new_level = 2'd1;
            default: new_level = 2'd0;
        endcase
    end

    always @(posedge clk) begin
        if (reset) begin
            level <= 2'd0;
            dfr_r <= 1'b1;
        end else begin
            level <= new_level;
            if (new_level > level)
                dfr_r <= 1'b1;
            else if (new_level < level)
                dfr_r <= 1'b0;
        end
    end

    always @(*) begin
        case (level)
            2'd0: begin
                fr2 = 1'b1; fr1 = 1'b1; fr0 = 1'b1; dfr = 1'b1;
            end
            2'd1: begin
                fr2 = 1'b0; fr1 = 1'b1; fr0 = 1'b1; dfr = dfr_r;
            end
            2'd2: begin
                fr2 = 1'b0; fr1 = 1'b0; fr0 = 1'b1; dfr = dfr_r;
            end
            default: begin
                fr2 = 1'b0; fr1 = 1'b0; fr0 = 1'b0; dfr = 1'b0;
            end
        endcase
    end

endmodule

