module TopModule (
    input  clk,
    input  reset,
    input  data,
    output [3:0] count,
    output counting,
    output done,
    input  ack
);

    localparam S0    = 3'd0;
    localparam S1    = 3'd1;
    localparam S11   = 3'd2;
    localparam S110  = 3'd3;
    localparam SHIFT = 3'd4;
    localparam COUNT = 3'd5;
    localparam DONE  = 3'd6;

    reg [2:0] state;
    reg [3:0] delay;
    reg [1:0] shift_cnt;
    reg [9:0] cycle_cnt;

    assign count    = delay;
    assign counting = (state == COUNT);
    assign done     = (state == DONE);

    always @(posedge clk) begin
        if (reset) begin
            state     <= S0;
            delay     <= 4'd0;
            shift_cnt <= 2'd0;
            cycle_cnt <= 10'd0;
        end else begin
            case (state)
                S0: begin
                    if (data) state <= S1;
                    else      state <= S0;
                end
                S1: begin
                    if (data) state <= S11;
                    else      state <= S0;
                end
                S11: begin
                    if (data) state <= S11;
                    else      state <= S110;
                end
                S110: begin
                    if (data) begin
                        state     <= SHIFT;
                        shift_cnt <= 2'd0;
                    end else begin
                        state <= S0;
                    end
                end
                SHIFT: begin
                    delay     <= {delay[2:0], data};
                    shift_cnt <= shift_cnt + 2'd1;
                    if (shift_cnt == 2'd3) begin
                        state     <= COUNT;
                        cycle_cnt <= 10'd0;
                    end
                end
                COUNT: begin
                    if (cycle_cnt == 10'd999) begin
                        cycle_cnt <= 10'd0;
                        if (delay == 4'd0) begin
                            state <= DONE;
                        end else begin
                            delay <= delay - 4'd1;
                        end
                    end else begin
                        cycle_cnt <= cycle_cnt + 10'd1;
                    end
                end
                DONE: begin
                    if (ack) state <= S0;
                    else     state <= DONE;
                end
                default: state <= S0;
            endcase
        end
    end

endmodule

