module TopModule (
    input        clk,
    input        reset,
    input  [2:0] s,
    output       fr2,
    output       fr1,
    output       fr0,
    output       dfr
);

    // level: 0 = below s[0], 1 = between s[0] and s[1],
    //        2 = between s[1] and s[2], 3 = above s[2]
    reg [1:0] level;
    reg       rise;
    reg [1:0] new_level;

    always @(*) begin
        case (s)
            3'b111:  new_level = 2'd3;
            3'b011:  new_level = 2'd2;
            3'b001:  new_level = 2'd1;
            default: new_level = 2'd0;
        endcase
    end

    always @(posedge clk) begin
        if (reset) begin
            level <= 2'd0;
            rise  <= 1'b1;
        end else begin
            level <= new_level;
            if (new_level > level)
                rise <= 1'b1;
            else if (new_level < level)
                rise <= 1'b0;
            else
                rise <= rise;
        end
    end

    assign fr2 = (level == 2'd0);
    assign fr1 = (level == 2'd0) || (level == 2'd1);
    assign fr0 = (level != 2'd3);
    assign dfr = (level == 2'd0) || ((level != 2'd3) && rise);

endmodule

