    output wire       counting,
    output wire       done,
    input  wire       ack
);

    localparam [3:0] S     = 4'd0,
                     S1    = 4'd1,
                     S11   = 4'd2,
                     S110  = 4'd3,
                     B0    = 4'd4,
                     B1    = 4'd5,
                     B2    = 4'd6,
                     B3    = 4'd7,
                     COUNT = 4'd8,
                     WAIT  = 4'd9;

    reg [3:0] state, next;
    reg [3:0] delay;
    reg [9:0] cnt;

    wire last_cycle = (state == COUNT) && (cnt == 10'd999) && (delay == 4'd0);

    always @(*) begin
        case (state)
            S:     next = data ? S1   : S;
            S1:    next = data ? S11  : S;
            S11:   next = data ? S11  : S110;
            S110:  next = data ? B0   : S;
            B0:    next = B1;
            B1:    next = B2;
            B2:    next = B3;
            B3:    next = COUNT;
            COUNT: next = last_cycle ? WAIT : COUNT;
            WAIT:  next = ack ? S : WAIT;
            default: next = S;
        endcase
    end

    always @(posedge clk) begin
        if (reset) begin
            state <= S;
            delay <= 4'd0;
            cnt   <= 10'd0;
