                        if (delay != 4'd0)
                            delay <= delay - 4'd1;
                    end else begin
                        cnt <= cnt + 10'd1;
                    end
                end
                default: begin
                    cnt <= 10'd0;
                end
            endcase
        end
    end

    assign count    = delay;
    assign counting = (state == COUNT);
    assign done     = (state == WAIT);

