                if (ground) next_state = (cnt > 5'd19) ? SPLAT : WL;
                else        next_state = FL;
            end
            FR: begin
                if (ground) next_state = (cnt > 5'd19) ? SPLAT : WR;
                else        next_state = FR;
            end
            DL: begin
                if (!ground) next_state = FL;
                else         next_state = DL;
            end
            DR: begin
                if (!ground) next_state = FR;
                else         next_state = DR;
            end
            SPLAT: next_state = SPLAT;
            default: next_state = WL;
        endcase
    end

    always @(posedge clk or posedge areset) begin
        if (areset)
            state <= WL;
        else
            state <= next_state;
    end

    always @(posedge clk or posedge areset) begin
        if (areset)
            cnt <= 5'd0;
        else if (state == FL || state == FR) begin
            if (cnt != 5'd31)
                cnt <= cnt + 5'd1;
        end
        else
            cnt <= 5'd0;
    end

    assign walk_left  = (state == WL);
    assign walk_right = (state == WR);
    assign aaah       = (state == FL) || (state == FR);
    assign digging    = (state == DL) || (state == DR);

endmodule
