module TopModule (
    input  clk,
    input  reset,
    output [2:0] ena,
    output [15:0] q
);

    // Enable signals for digits [3:1]
    assign ena[0] = (q[3:0] == 4'd9);
    assign ena[1] = (q[3:0] == 4'd9) && (q[7:4] == 4'd9);
    assign ena[2] = (q[3:0] == 4'd9) && (q[7:4] == 4'd9) && (q[11:8] == 4'd9);

    // BCD counter with synchronous active-high reset
    always @(posedge clk) begin
        if (reset) begin
            q <= 16'h0000;
        end else begin
            // Ones digit always increments
            q[3:0] <= (q[3:0] == 4'd9) ? 4'd0 : q[3:0] + 4'd1;

            // Tens digit
            if (ena[0])
                q[7:4] <= (q[7:4] == 4'd9) ? 4'd0 : q[7:4] + 4'd1;

            // Hundreds digit
            if (ena[1])
                q[11:8] <= (q[11:8] == 4'd9) ? 4'd0 : q[11:8] + 4'd1;

            // Thousands digit
            if (ena[2])
                q[15:12] <= (q[15:12] == 4'd9) ? 4'd0 : q[15:12] + 4'd1;
        end
    end

endmodule

