module TopModule (
    input  clk,
    input  reset,
    input  data,
    output start_shifting
);

    localparam [2:0] S0 = 3'd0,  // no prefix matched
                     S1 = 3'd1,  // matched "1"
                     S2 = 3'd2,  // matched "11"
                     S3 = 3'd3,  // matched "110"
                     S4 = 3'd4;  // matched "1101" (sticky)

    reg [2:0] state, next_state;

    // State register: synchronous, active-high reset
    always @(posedge clk) begin
        if (reset)
            state <= S0;
        else
            state <= next_state;
    end

    // Next-state logic
    always @(*) begin
        case (state)
            S0: next_state = data ? S1 : S0;
            S1: next_state = data ? S2 : S0;
            S2: next_state = data ? S2 : S3;
            S3: next_state = data ? S4 : S0;
            S4: next_state = S4;
            default: next_state = S0;
        endcase
    end

    // Moore output: high once the sequence has been found
    assign start_shifting = (state == S4);

endmodule

