module TopModule (
    input  clk,
    input  areset,
    input  x,
    output z
);
    // State: {previous input bit, carry into previous input bit}
    reg [1:0] state;
    wire [1:0] next_state;

    // Next state: capture the current input bit, and update carry = prev_x | carry
    assign next_state = {x, state[1] | state[0]};

    always @(posedge clk or posedge areset) begin
        if (areset)
            state <= 2'b00;
        else
            state <= next_state;
    end

    // Moore output: z = x_prev XOR carry_prev, depends only on state
    assign z = state[1] ^ state[0];
endmodule

