module TopModule (
    input  clk,
    input  reset,
    input  in,
    output done
);

    localparam IDLE = 3'd0,
               DATA = 3'd1,
               STOP = 3'd2,
               DONE = 3'd3,
               ERR  = 3'd4;

    reg [2:0] state;
    reg [2:0] next_state;
    reg [2:0] cnt;

    // State register (synchronous, active-high reset)
    always @(posedge clk) begin
        if (reset)
            state <= IDLE;
        else
            state <= next_state;
    end

    // Bit counter for the 8 data bits
    always @(posedge clk) begin
        if (reset)
            cnt <= 3'd0;
        else if (state == DATA)
            cnt <= cnt + 3'd1;
        else
            cnt <= 3'd0;
    end

    // Next-state logic
    always @(*) begin
        case (state)
            IDLE: next_state = in ? IDLE : DATA;               // start bit (0) detected
            DATA: next_state = (cnt == 3'd7) ? STOP : DATA;    // receive 8 data bits, LSB first
            STOP: next_state = in ? DONE : ERR;                // stop bit must be 1
            DONE: next_state = in ? IDLE : DATA;               // byte done; 0 here is next start bit
            ERR:  next_state = in ? IDLE : ERR;                // wait for a stop (idle) level
            default: next_state = IDLE;
        endcase
    end

    // Output: asserted for one cycle when a byte is correctly received
    assign done = (state == DONE);

endmodule

