module TopModule (
    input  clk,
    input  reset,
    input  in,
    output disc,
    output flag,
    output err
);

    localparam [3:0] S0 = 4'd0,  // no trailing 1s (previous input 0)
                     S1 = 4'd1,  // 1 consecutive 1
                     S2 = 4'd2,  // 2 consecutive 1s
                     S3 = 4'd3,  // 3 consecutive 1s
                     S4 = 4'd4,  // 4 consecutive 1s
                     S5 = 4'd5,  // 5 consecutive 1s
                     S6 = 4'd6,  // 6 consecutive 1s
                     E  = 4'd7,  // 7 or more consecutive 1s (error)
                     D  = 4'd8,  // 0 seen after 5 ones (disc)
                     F  = 4'd9;  // 0 seen after 6 ones (flag)

    reg [3:0] state, next_state;

    // State register (synchronous, active-high reset)
    always @(posedge clk) begin
        if (reset)
            state <= S0;
        else
            state <= next_state;
    end

    // Next-state logic
    always @(*) begin
        case (state)
            S0: next_state = in ? S1 : S0;
            S1: next_state = in ? S2 : S0;
            S2: next_state = in ? S3 : S0;
            S3: next_state = in ? S4 : S0;
            S4: next_state = in ? S5 : S0;
            S5: next_state = in ? S6 : D;
            S6: next_state = in ? E  : F;
            E : next_state = in ? E  : S0;
            D : next_state = in ? S1 : S0;
            F : next_state = in ? S1 : S0;
            default: next_state = S0;
        endcase
    end

    // Moore outputs (depend only on current state)
    assign disc = (state == D);
    assign flag = (state == F);
    assign err  = (state == E);

endmodule

