module TopModule (
    input clk,
    input load,
    input [255:0] data,
    output reg [255:0] q
);

    wire [255:0] next_q;

    genvar r, c;
    generate
        for (r = 0; r < 16; r = r + 1) begin : row
            for (c = 0; c < 16; c = c + 1) begin : col
                localparam UP = (r + 15) % 16;
                localparam DN = (r + 1) % 16;
                localparam LF = (c + 15) % 16;
                localparam RT = (c + 1) % 16;

                wire [3:0] cnt;
                assign cnt = q[UP*16 + LF] + q[UP*16 + c] + q[UP*16 + RT]
                           + q[r*16  + LF] +                q[r*16  + RT]
                           + q[DN*16 + LF] + q[DN*16 + c] + q[DN*16 + RT];

                assign next_q[r*16 + c] = (cnt == 4'd3) | ((cnt == 4'd2) & q[r*16 + c]);
            end
        end
    endgenerate

    always @(posedge clk) begin
        if (load)
            q <= data;
        else
            q <= next_q;
    end

endmodule

