module TopModule (
  input  clk,
  input  in,
  input  reset,
  output reg [7:0] out_byte,
  output reg done
);

  localparam IDLE = 2'd0;
  localparam DATA = 2'd1;
  localparam STOP = 2'd2;
  localparam ERR  = 2'd3;

  reg [1:0] state;
  reg [2:0] count;
  reg [7:0] shreg;

  always @(posedge clk) begin
    if (reset) begin
      state    <= IDLE;
      count    <= 3'd0;
      shreg    <= 8'd0;
      out_byte <= 8'd0;
      done     <= 1'b0;
    end else begin
      done <= 1'b0;
      case (state)
        IDLE: begin
          if (in == 1'b0) begin
            state <= DATA;
            count <= 3'd0;
          end
        end

        DATA: begin
          // LSB first: shift new bit into MSB, so after 8 shifts bit0 is in position 0
          shreg <= {in, shreg[7:1]};
          count <= count + 3'd1;
          if (count == 3'd7)
            state <= STOP;
        end

        STOP: begin
          if (in == 1'b1) begin
            out_byte <= shreg;
            done     <= 1'b1;
            state    <= IDLE;
          end else begin
            state <= ERR;
          end
        end

        ERR: begin
          // Framing error: wait for the line to return to idle (stop/mark level)
          if (in == 1'b1)
            state <= IDLE;
        end

        default: state <= IDLE;
      endcase
    end
  end

