module TopModule (
    input        clk,
    input        reset,
    input  [2:0] s,
    output       fr2,
    output       fr1,
    output       fr0,
    output       dfr
);

    reg  [2:0] s_prev;    // sensor reading at the last sensor change
    reg        rising;    // 1 if the last sensor change was a rise in level
    reg  [2:0] fr;        // {fr2, fr1, fr0}
    reg        dfr_r;
    wire       rise_now;  // direction of the most recent sensor change

    // A change in the thermometer-coded sensors is a rise when the new value
    // is numerically greater. Otherwise keep the previously recorded direction.
    assign rise_now = (s != s_prev) ? (s > s_prev) : rising;

    always @(posedge clk) begin
        if (reset) begin
            s_prev <= 3'b000;   // equivalent to a long-term low water level
            rising <= 1'b1;     // all outputs asserted
        end else begin
            s_prev <= s;
            rising <= rise_now;
        end
    end

    always @(*) begin
        case (s)
            3'b111: begin       // above s[2]: no flow
                fr    = 3'b000;
                dfr_r = 1'b0;
            end
            3'b011: begin       // between s[2] and s[1]: fr0
                fr    = 3'b001;
                dfr_r = rise_now;
            end
            3'b001: begin       // between s[1] and s[0]: fr0, fr1
                fr    = 3'b011;
                dfr_r = rise_now;
            end
            default: begin      // below s[0]: fr0, fr1, fr2 and dfr
                fr    = 3'b111;
                dfr_r = 1'b1;
            end
        endcase
    end

    assign {fr2, fr1, fr0} = fr;
    assign dfr             = dfr_r;

endmodule

