module TopModule (
    input  clk,
    input  reset,
    input  data,
    output [3:0] count,
    output counting,
    output done,
    input  ack
);

    localparam [1:0] S_SEARCH = 2'd0,
                     S_DELAY  = 2'd1,
                     S_COUNT  = 2'd2,
                     S_DONE   = 2'd3;

    reg [1:0] state;
    reg [3:0] sr;      // shift register for 1101 detection
    reg [1:0] bitcnt;  // counts the 4 delay bits
    reg [3:0] rem;     // delay value, then remaining thousands count
    reg [9:0] cyc;     // cycles within current 1000-cycle block

    assign count    = rem;
    assign counting = (state == S_COUNT);
    assign done     = (state == S_DONE);

    always @(posedge clk) begin
        if (reset) begin
            state  <= S_SEARCH;
            sr     <= 4'd0;
            bitcnt <= 2'd0;
            rem    <= 4'd0;
            cyc    <= 10'd0;
        end else begin
            case (state)
                S_SEARCH: begin
                    sr <= {sr[2:0], data};
                    if ({sr[2:0], data} == 4'b1101) begin
                        state  <= S_DELAY;
                        bitcnt <= 2'd0;
                    end
                end

                S_DELAY: begin
                    // Shift in delay[3:0], MSB first
                    rem    <= {rem[2:0], data};
                    bitcnt <= bitcnt + 2'd1;
                    if (bitcnt == 2'd3) begin
                        state <= S_COUNT;
                        cyc   <= 10'd0;
                    end
                end

                S_COUNT: begin
                    if (cyc == 10'd999) begin
                        cyc <= 10'd0;
                        if (rem == 4'd0) begin
                            state <= S_DONE;
                        end else begin
                            rem <= rem - 4'd1;
                        end
                    end else begin
                        cyc <= cyc + 10'd1;
                    end
                end

                S_DONE: begin
                    if (ack) begin
                        state <= S_SEARCH;
                        sr    <= 4'd0;
                    end
                end

                default: state <= S_SEARCH;
            endcase
        end
    end

endmodule

