    input  areset,
    input  bump_left,
    input  bump_right,
    input  ground,
    input  dig,
    output walk_left,
    output walk_right,
    output aaah,
    output digging
);

    localparam [2:0] WL = 3'd0,   // walking left
                     WR = 3'd1,   // walking right
                     FL = 3'd2,   // falling, original direction left
                     FR = 3'd3,   // falling, original direction right
                     DL = 3'd4,   // digging, direction left
                     DR = 3'd5,   // digging, direction right
                     SP = 3'd6;   // splattered (terminal)

    reg [2:0] state, next_state;
    reg [4:0] fall_cnt;

    // State register (asynchronous active-high reset to walk left)
    always @(posedge clk or posedge areset) begin
        if (areset)
            state <= WL;
        else
            state <= next_state;
    end

    // Next-state logic
    always @(*) begin
        next_state = state;
        case (state)
            WL: begin
                if (!ground)          next_state = FL;   // fall has highest priority
                else if (dig)         next_state = DL;   // dig next
                else if (bump_left)   next_state = WR;   // bumped on left -> walk right
                else                  next_state = WL;
            end

            WR: begin
                if (!ground)          next_state = FR;
                else if (dig)         next_state = DR;
                else if (bump_right)  next_state = WL;   // bumped on right -> walk left
                else                  next_state = WR;
            end

            FL: begin
                if (ground) begin
                    if (fall_cnt > 5'd20) next_state = SP;  // fell too long: splatter
                    else                  next_state = WL;  // resume walking left
                end else
                    next_state = FL;
            end

            FR: begin
                if (ground) begin
                    if (fall_cnt > 5'd20) next_state = SP;
                    else                  next_state = WR;
                end else
                    next_state = FR;
            end

            DL: begin
                if (!ground) next_state = FL;  // no ground: fall, keep direction
                else         next_state = DL;  // keep digging, ignore bumps/dig
            end

            DR: begin
                if (!ground) next_state = FR;
                else         next_state = DR;
            end

            SP: next_state = SP;               // stays splattered until reset

            default: next_state = WL;
        endcase
    end

    // Fall-duration counter: counts cycles spent falling, saturates at 21
    always @(posedge clk or posedge areset) begin
        if (areset)
            fall_cnt <= 5'd0;
        else if ((state == FL || state == FR) && !ground) begin
            if (fall_cnt < 5'd21)
                fall_cnt <= fall_cnt + 5'd1;
        end
        else
            fall_cnt <= 5'd0;
    end

    // Moore outputs (depend only on state)
    assign walk_left  = (state == WL);
    assign walk_right = (state == WR);
    assign aaah       = (state == FL) || (state == FR);
    assign digging    = (state == DL) || (state == DR);

