module TopModule (
    input  clk,
    input  d,
    output q
);

    reg p;  // captured on posedge
    reg n;  // captured on negedge

    always @(posedge clk) begin
        p <= d;
    end

    always @(negedge clk) begin
        n <= d;
    end

    // When clk is high, the last edge was a posedge -> output p.
    // When clk is low, the last edge was a negedge -> output n.
    assign q = clk ? p : n;

endmodule

