    reg [1:0] next_state;

    localparam A = 0;
    localparam B = 1;

    always @(*) begin
        next_state[A] = state[A] & ~x;
        next_state[B] = state[B] | (state[A] & x);
    end

    always @(posedge clk or posedge areset) begin
        if (areset)
            state <= 2'b01;
        else
            state <= next_state;
    end

    assign z = (state[A] & x) | (state[B] & ~x);

