module TopModule (
    input  clk,
    input  areset,
    input  x,
    output z
);

    localparam A = 2'd0;  // no 1 seen yet, output 0
    localparam B = 2'd1;  // output 1 (seen a 1)
    localparam C = 2'd2;  // output 0 (seen a 1)

    reg [1:0] state, next_state;

    always @(posedge clk or posedge areset) begin
        if (areset)
            state <= A;
        else
            state <= next_state;
    end

    always @(*) begin
        case (state)
            A: next_state = x ? B : A;
            B: next_state = x ? C : B;
            C: next_state = x ? C : B;
            default: next_state = A;
        endcase
    end

    assign z = (state == B);

endmodule

