module TopModule (
    input clk,
    input in,
    input reset,
    output [7:0] out_byte,
    output done
);

    localparam IDLE = 3'd0,
               DATA = 3'd1,
               STOP = 3'd2,
               DONE = 3'd3,
               WAIT = 3'd4;

    reg [2:0] state, next_state;
    reg [2:0] cnt;
    reg [7:0] data;

    always @(*) begin
        case (state)
            IDLE: next_state = in ? IDLE : DATA;
            DATA: next_state = (cnt == 3'd7) ? STOP : DATA;
            STOP: next_state = in ? DONE : WAIT;
            DONE: next_state = in ? IDLE : DATA;
            WAIT: next_state = in ? IDLE : WAIT;
            default: next_state = IDLE;
        endcase
    end

    always @(posedge clk) begin
        if (reset) begin
            state <= IDLE;
            cnt   <= 3'd0;
            data  <= 8'd0;
        end else begin
            state <= next_state;
            if (state == DATA) begin
                data <= {in, data[7:1]};
                cnt  <= cnt + 3'd1;
            end else begin
                cnt <= 3'd0;
            end
        end
    end

    assign out_byte = data;
    assign done = (state == DONE);

endmodule

