module TopModule (
    input        clk,
    input        reset,
    input        data,
    output [3:0] count,
    output       counting,
    output       done,
    input        ack
);

    localparam S_IDLE  = 4'd0;
    localparam S_1     = 4'd1;
    localparam S_11    = 4'd2;
    localparam S_110   = 4'd3;
    localparam S_B0    = 4'd4;
    localparam S_B1    = 4'd5;
    localparam S_B2    = 4'd6;
    localparam S_B3    = 4'd7;
    localparam S_COUNT = 4'd8;
    localparam S_DONE  = 4'd9;

    reg [3:0]  state;
    reg [3:0]  delay;
    reg [9:0]  cnt;

    always @(posedge clk) begin
        if (reset) begin
            state <= S_IDLE;
            delay <= 4'd0;
            cnt   <= 10'd0;
        end else begin
            case (state)
                S_IDLE: begin
                    if (data) state <= S_1;
                    else      state <= S_IDLE;
                end
                S_1: begin
                    if (data) state <= S_11;
                    else      state <= S_IDLE;
                end
                S_11: begin
                    if (data) state <= S_11;
                    else      state <= S_110;
                end
                S_110: begin
                    if (data) state <= S_B0;
                    else      state <= S_IDLE;
                end
                S_B0: begin
                    delay[3] <= data;
                    state    <= S_B1;
                end
                S_B1: begin
                    delay[2] <= data;
                    state    <= S_B2;
                end
                S_B2: begin
                    delay[1] <= data;
                    state    <= S_B3;
                end
                S_B3: begin
                    delay[0] <= data;
                    cnt      <= 10'd0;
                    state    <= S_COUNT;
                end
                S_COUNT: begin
                    if (cnt == 10'd999) begin
                        cnt <= 10'd0;
                        if (delay == 4'd0) begin
                            state <= S_DONE;
                        end else begin
                            delay <= delay - 4'd1;
                        end
                    end else begin
                        cnt <= cnt + 10'd1;
                    end
                end
                S_DONE: begin
                    if (ack) state <= S_IDLE;
                    else     state <= S_DONE;
                end
                default: state <= S_IDLE;
            endcase
        end
    end

    assign counting = (state == S_COUNT);
    assign done     = (state == S_DONE);
    assign count    = delay;

endmodule

