module TopModule(
    input  clk,
    input  areset,
    input  bump_left,
    input  bump_right,
    input  ground,
    input  dig,
    output walk_left,
    output walk_right,
    output aaah,
    output digging
);

    parameter WL = 3'd0, WR = 3'd1, FL = 3'd2, FR = 3'd3,
              DL = 3'd4, DR = 3'd5, SPLAT = 3'd6;

    reg [2:0] state, next;
    reg [4:0] cnt;

    always @(*) begin
        case (state)
            WL: begin
                if (!ground)         next = FL;
                else if (dig)        next = DL;
                else if (bump_left)  next = WR;
                else                 next = WL;
            end
            WR: begin
                if (!ground)         next = FR;
                else if (dig)        next = DR;
                else if (bump_right) next = WL;
                else                 next = WR;
            end
            FL: begin
                if (ground) begin
                    if (cnt >= 5'd20) next = SPLAT;
                    else              next = WL;
                end else next = FL;
            end
            FR: begin
                if (ground) begin
                    if (cnt >= 5'd20) next = SPLAT;
                    else              next = WR;
                end else next = FR;
            end
            DL: next = ground ? DL : FL;
            DR: next = ground ? DR : FR;
            SPLAT: next = SPLAT;
            default: next = WL;
        endcase
    end

    always @(posedge clk or posedge areset) begin
        if (areset) begin
            state <= WL;
            cnt   <= 5'd0;
        end else begin
            state <= next;
            if (next == FL || next == FR) begin
                if (state == FL || state == FR) begin
                    if (cnt < 5'd20)
                        cnt <= cnt + 5'd1;
                end else
                    cnt <= 5'd0;
            end else
                cnt <= 5'd0;
        end
    end

    assign walk_left  = (state == WL);
    assign walk_right = (state == WR);
    assign aaah       = (state == FL) || (state == FR);
    assign digging    = (state == DL) || (state == DR);

endmodule

