module TopModule (
  input  clk,
  input  reset,
  input  in,
  output disc,
  output flag,
  output err
);

  // States: S0..S6 count consecutive 1s (S0 = previous input was 0)
  // SDISC: saw 0111110, SFLAG: saw 01111110, SERR: 7+ ones
  localparam [3:0] S0    = 4'd0,
                   S1    = 4'd1,
                   S2    = 4'd2,
                   S3    = 4'd3,
                   S4    = 4'd4,
                   S5    = 4'd5,
                   S6    = 4'd6,
                   SERR  = 4'd7,
                   SDISC = 4'd8,
                   SFLAG = 4'd9;

  reg [3:0] state, next_state;

  always @(*) begin
    case (state)
      S0:    next_state = in ? S1    : S0;
      S1:    next_state = in ? S2    : S0;
      S2:    next_state = in ? S3    : S0;
      S3:    next_state = in ? S4    : S0;
      S4:    next_state = in ? S5    : S0;
      S5:    next_state = in ? S6    : SDISC;
      S6:    next_state = in ? SERR  : SFLAG;
      SERR:  next_state = in ? SERR  : S0;
      SDISC: next_state = in ? S1    : S0;
      SFLAG: next_state = in ? S1    : S0;
      default: next_state = S0;
    endcase
  end

  always @(posedge clk) begin
    if (reset)
      state <= S0;
    else
      state <= next_state;
  end

  assign disc = (state == SDISC);
  assign flag = (state == SFLAG);
  assign err  = (state == SERR);

endmodule

