    input  in,
    input  reset,
    output [7:0] out_byte,
    output done
);

    localparam IDLE = 3'd0,
               DATA = 3'd1,
               STOP = 3'd2,
               DONE = 3'd3,
               ERR  = 3'd4;

    reg [2:0] state, next_state;
    reg [3:0] cnt;
    reg [7:0] shreg;

    always @(*) begin
        case (state)
            IDLE: next_state = in ? IDLE : DATA;
            DATA: next_state = (cnt == 4'd7) ? STOP : DATA;
            STOP: next_state = in ? DONE : ERR;
            DONE: next_state = in ? IDLE : DATA;
            ERR:  next_state = in ? IDLE : ERR;
            default: next_state = IDLE;
