    end

    always @(posedge clk) begin
        if (reset) begin
            state <= IDLE;
            cnt   <= 4'd0;
            shreg <= 8'd0;
        end else begin
            state <= next_state;
            if (state == DATA) begin
                shreg <= {in, shreg[7:1]};
                cnt   <= cnt + 4'd1;
            end else begin
                cnt <= 4'd0;
            end
        end
    end

    assign done     = (state == DONE);
    assign out_byte = shreg;

endmodule

