    input        reset,
    input  [2:0] s,
    output       fr2,
    output       fr1,
    output       fr0,
    output       dfr
);

    reg [1:0] level;
    reg       dfr_r;
    reg [1:0] new_level;

    always @(*) begin
        case (s)
            3'b111:  new_level = 2'd3;
            3'b011:  new_level = 2'd2;
            3'b001:  new_level = 2'd1;
            default: new_level = 2'd0;
        endcase
    end

    always @(posedge clk) begin
        if (reset) begin
            level <= 2'd0;
            dfr_r <= 1'b1;
        end else begin
            level <= new_level;
            if (new_level != level)
                dfr_r <= (new_level > level);
        end
