        if (areset)
            count <= 5'd0;
        else if (falling) begin
            if (count != 5'd31)
                count <= count + 5'd1;
        end
        else
            count <= 5'd0;
    end

    assign walk_left  = (state == WL);
    assign walk_right = (state == WR);
    assign aaah       = falling;
    assign digging    = (state == DL) || (state == DR);

endmodule

