module TopModule (
    input  wire       clk,
    input  wire       reset,
    input  wire       data,
    output wire [3:0] count,
    output wire       counting,
    output wire       done,
    input  wire       ack
);

    localparam S     = 4'd0,
               S1    = 4'd1,
               S11   = 4'd2,
               S110  = 4'd3,
               B0    = 4'd4,
               B1    = 4'd5,
               B2    = 4'd6,
               B3    = 4'd7,
               CNT   = 4'd8,
               WAIT  = 4'd9;

    reg [3:0] state, next;
    reg [3:0] delay;
    reg [9:0] cyc;

    wire cnt_done = (state == CNT) && (delay == 4'd0) && (cyc == 10'd999);

    always @(*) begin
        case (state)
            S:     next = data ? S1   : S;
            S1:    next = data ? S11  : S;
            S11:   next = data ? S11  : S110;
            S110:  next = data ? B0   : S;
            B0:    next = B1;
            B1:    next = B2;
            B2:    next = B3;
            B3:    next = CNT;
            CNT:   next = cnt_done ? WAIT : CNT;
            WAIT:  next = ack ? S : WAIT;
            default: next = S;
        endcase
    end

    always @(posedge clk) begin
        if (reset)
            state <= S;
        else
            state <= next;
    end

    always @(posedge clk) begin
        if (reset) begin
            delay <= 4'd0;
            cyc   <= 10'd0;
        end else begin
            case (state)
                B0, B1, B2, B3: begin
                    delay <= {delay[2:0], data};
                    cyc   <= 10'd0;
                end
                CNT: begin
                    if (cyc == 10'd999) begin
                        cyc   <= 10'd0;
                        delay <= delay - 4'd1;
                    end else begin
                        cyc <= cyc + 10'd1;
                    end
                end
                default: begin
                    cyc <= 10'd0;
                end
