module TopModule (
    input  wire mode,
    input  wire too_cold,
    input  wire too_hot,
    input  wire fan_on,
    output wire heater,
    output wire aircon,
    output wire fan
);

    // Heating mode (mode = 1): heater runs when too cold.
    // Cooling mode (mode = 0): air conditioner runs when too hot.
    // Heater and air conditioner are mutually exclusive by mode.
    assign heater = mode & too_cold;
    assign aircon = ~mode & too_hot;

    // Fan runs when heater or air conditioner is on, or when requested.
    assign fan = fan_on | heater | aircon;

endmodule

