    input  [3:0] state,
    output [3:0] next_state,
    output out
);

    // One-hot state encoding: state[0]=A, state[1]=B, state[2]=C, state[3]=D

    // next_state[0] (A): reached from A and C with in=0
    assign next_state[0] = (state[0] | state[2]) & ~in;

    // next_state[1] (B): reached from A, B, and D with in=1
    assign next_state[1] = (state[0] | state[1] | state[3]) & in;

    // next_state[2] (C): reached from B and D with in=0
    assign next_state[2] = (state[1] | state[3]) & ~in;

    // next_state[3] (D): reached from C with in=1
    assign next_state[3] = state[2] & in;

    // Moore output: 1 only in state D
    assign out = state[3];

endmodule

