module TopModule (
    input  wire clk,
    input  wire reset,
    input  wire in,
    output wire done
);

    localparam IDLE    = 3'd0;
    localparam DATA    = 3'd1;
    localparam STOP    = 3'd2;
    localparam DONE_S  = 3'd3;
    localparam WAIT    = 3'd4;

    reg [2:0] state, next_state;
    reg [3:0] cnt;
    reg [7:0] shreg;

    assign done = (state == DONE_S);

    always @(posedge clk) begin
        if (reset) begin
            state <= IDLE;
            cnt   <= 4'd0;
            shreg <= 8'd0;
        end else begin
            state <= next_state;
            case (state)
                IDLE: begin
                    if (!in) cnt <= 4'd0;
                end
                DATA: begin
                    shreg <= {in, shreg[7:1]};
                    cnt   <= cnt + 4'd1;
                end
                default: ;
            endcase
        end
    end

    always @(*) begin
        next_state = state;
        case (state)
            IDLE: begin
                if (!in) next_state = DATA;
            end
            DATA: begin
                if (cnt == 4'd7) next_state = STOP;
            end
            STOP: begin
                if (in) next_state = DONE_S;
                else    next_state = WAIT;
            end
            DONE_S: begin
                if (!in) next_state = DATA;
                else     next_state = IDLE;
            end
            WAIT: begin
                if (in) next_state = IDLE;
            end
            default: next_state = IDLE;
        endcase
    end

endmodule

