module TopModule (
    input clk,
    input load,
    input [255:0] data,
    output reg [255:0] q
);

    wire [255:0] next_q;

    genvar r, c;
    generate
        for (r = 0; r < 16; r = r + 1) begin : row
            for (c = 0; c < 16; c = c + 1) begin : col
                localparam UP    = (r + 15) % 16;
                localparam DOWN  = (r + 1) % 16;
                localparam LEFT  = (c + 15) % 16;
                localparam RIGHT = (c + 1) % 16;

                wire [3:0] n;
                assign n = q[UP*16    + LEFT]  + q[UP*16    + c]     + q[UP*16    + RIGHT]
                         + q[r*16     + LEFT]                       + q[r*16     + RIGHT]
                         + q[DOWN*16  + LEFT]  + q[DOWN*16  + c]     + q[DOWN*16  + RIGHT];

                // 0-1 neighbours -> 0, 2 -> hold, 3 -> 1, 4+ -> 0
                assign next_q[r*16 + c] = (n == 4'd3) | ((n == 4'd2) & q[r*16 + c]);
            end
        end
    endgenerate

    always @(posedge clk) begin
        if (load)
            q <= data;
        else
            q <= next_q;
    end

endmodule

