    always @(posedge clk) begin
        if (!resetn)
            present_state <= A;
        else
            present_state <= next_state;
    end

    // Moore outputs
    assign g[0] = (present_state == B);
    assign g[1] = (present_state == C);
    assign g[2] = (present_state == D);

