module TopModule (
    input  clk,
    input  in,
    input  reset,
    output reg [7:0] out_byte,
    output reg done
);

    localparam IDLE = 2'd0;
    localparam DATA = 2'd1;
    localparam STOP = 2'd2;
    localparam WAIT = 2'd3;

    reg [1:0] state;
    reg [2:0] count;
    reg [7:0] shreg;

    always @(posedge clk) begin
        if (reset) begin
            state    <= IDLE;
            count    <= 3'd0;
            shreg    <= 8'd0;
            out_byte <= 8'd0;
            done     <= 1'b0;
        end else begin
            done <= 1'b0;
            case (state)
                IDLE: begin
                    if (!in) begin
                        state <= DATA;
                        count <= 3'd0;
                    end
                end

                DATA: begin
                    shreg <= {in, shreg[7:1]};
                    count <= count + 3'd1;
                    if (count == 3'd7)
                        state <= STOP;
                end

                STOP: begin
                    if (in) begin
                        done     <= 1'b1;
                        out_byte <= shreg;
                        state    <= IDLE;
                    end else begin
                        state <= WAIT;
                    end
                end

                WAIT: begin
                    if (in)
                        state <= IDLE;
                end

                default: state <= IDLE;
            endcase
        end
    end

endmodule

