module TopModule (
    input  clock,
    input  a,
    output reg p,
    output reg q
);

    // p: transparent latch, follows a while clock is high and holds while clock is low
    always @(clock or a) begin
        if (clock)
            p = a;
    end

    // q: negative-edge-triggered flip-flop capturing a
    always @(negedge clock) begin
        q <= a;
    end

endmodule

