module TopModule (
    input  clk,
    input  reset,
    input  s,
    input  w,
    output z
);

    localparam [2:0]
        A    = 3'd0,   // waiting for s = 1
        B    = 3'd1,   // start of a 3-cycle window, count = 0, z = 0
        F1   = 3'd2,   // start of a 3-cycle window, count = 0, z = 1
        P2C0 = 3'd3,   // 1 sample taken in window, count = 0
        P2C1 = 3'd4,   // 1 sample taken in window, count = 1
        P3C0 = 3'd5,   // 2 samples taken in window, count = 0
        P3C1 = 3'd6,   // 2 samples taken in window, count = 1
        P3C2 = 3'd7;   // 2 samples taken in window, count = 2

    reg [2:0] state, next_state;

    always @(posedge clk) begin
        if (reset)
            state <= A;
        else
            state <= next_state;
    end

    always @(*) begin
        case (state)
            A:    next_state = s ? B : A;
            B:    next_state = w ? P2C1 : P2C0;
            F1:   next_state = w ? P2C1 : P2C0;
            P2C0: next_state = w ? P3C1 : P3C0;
            P2C1: next_state = w ? P3C2 : P3C1;
            P3C0: next_state = B;
            P3C1: next_state = w ? F1 : B;
            P3C2: next_state = w ? B  : F1;
            default: next_state = A;
        endcase
    end

    assign z = (state == F1);

endmodule

