module TopModule (
    input  clk,
    input  reset,
    input  data,
    output [3:0] count,
    output counting,
    output done,
    input  ack
);

    localparam [2:0] SRCH_0 = 3'd0,  // no prefix matched
                     SRCH_1 = 3'd1,  // matched "1"
                     SRCH_2 = 3'd2,  // matched "11"
                     SRCH_3 = 3'd3,  // matched "110"
                     SHIFT  = 3'd4,  // shifting in delay[3:0]
                     COUNT  = 3'd5,  // counting
                     DONE_S = 3'd6;  // waiting for ack

    reg [2:0] state;
    reg [1:0] shift_cnt;
    reg [3:0] cur;      // delay value, then remaining time
    reg [9:0] ms_cnt;   // counts 0..999 clock cycles

    always @(posedge clk) begin
        if (reset) begin
            state     <= SRCH_0;
            shift_cnt <= 2'd0;
            cur       <= 4'd0;
            ms_cnt    <= 10'd0;
        end else begin
            case (state)
                SRCH_0: begin
                    if (data) state <= SRCH_1;
                end

                SRCH_1: begin
                    state <= data ? SRCH_2 : SRCH_0;
                end

                SRCH_2: begin
                    state <= data ? SRCH_2 : SRCH_3;
                end

                SRCH_3: begin
                    if (data) begin
                        state     <= SHIFT;
                        shift_cnt <= 2'd0;
                    end else begin
                        state <= SRCH_0;
                    end
                end

                SHIFT: begin
                    cur       <= {cur[2:0], data};
                    shift_cnt <= shift_cnt + 2'd1;
                    if (shift_cnt == 2'd3) begin
                        state  <= COUNT;
                        ms_cnt <= 10'd0;
                    end
                end

                COUNT: begin
                    if (ms_cnt == 10'd999) begin
                        ms_cnt <= 10'd0;
                        if (cur == 4'd0)
                            state <= DONE_S;
                        else
                            cur <= cur - 4'd1;
                    end else begin
                        ms_cnt <= ms_cnt + 10'd1;
                    end
                end

                DONE_S: begin
                    if (ack) state <= SRCH_0;
                end

                default: state <= SRCH_0;
            endcase
        end
    end

    assign count    = cur;
    assign counting = (state == COUNT);
    assign done     = (state == DONE_S);

endmodule

