[BEGIN]
module TopModule (
  input  clk,
  input  areset,
  input  bump_left,
  input  bump_right,
  input  ground,
  input  dig,
  output walk_left,
  output walk_right,
  output aaah,
  output digging
);

  localparam [2:0] WL = 3'd0,  // walking left
                   WR = 3'd1,  // walking right
                   FL = 3'd2,  // falling, was walking left
                   FR = 3'd3,  // falling, was walking right
                   DL = 3'd4,  // digging, walking left
                   DR = 3'd5,  // digging, walking right
                   SP = 3'd6;  // splattered (terminal until reset)

  reg [2:0] state, next_state;
  reg [4:0] cnt;  // counts clock cycles spent falling (saturates at 21)

  // State and fall-counter register
  always @(posedge clk or posedge areset) begin
    if (areset) begin
      state <= WL;
      cnt   <= 5'd0;
    end else begin
      state <= next_state;
      if ((state == FL || state == FR) && !ground) begin
        if (cnt < 5'd21)
          cnt <= cnt + 5'd1;
      end else begin
        cnt <= 5'd0;
      end
    end
  end

  // Next-state logic
  always @(*) begin
    next_state = state;
    case (state)
      WL: begin
        if (!ground)
          next_state = FL;
        else if (dig)
          next_state = DL;
        else if (bump_left)
          next_state = WR;
      end

      WR: begin
        if (!ground)
          next_state = FR;
        else if (dig)
          next_state = DR;
        else if (bump_right)
          next_state = WL;
      end

      DL: begin
        if (!ground)
          next_state = FL;
      end

      DR: begin
        if (!ground)
          next_state = FR;
      end

      FL: begin
        if (ground)
          next_state = (cnt > 5'd20) ? SP : WL;
      end

      FR: begin
        if (ground)
          next_state = (cnt > 5'd20) ? SP : WR;
      end

      SP: next_state = SP;

      default: next_state = WL;
    endcase
  end

  // Moore outputs (depend only on state)
  assign walk_left  = (state == WL);
  assign walk_right = (state == WR);
  assign aaah       = (state == FL) || (state == FR);
  assign digging    = (state == DL) || (state == DR);

endmodule
