module TopModule (
    input clk,
    input reset,
    output [3:1] ena,
    output [15:0] q
);

    wire inc0 = 1'b1;
    wire inc1 = (q[3:0] == 4'd9);
    wire inc2 = (q[3:0] == 4'd9) && (q[7:4] == 4'd9);
    wire inc3 = (q[3:0] == 4'd9) && (q[7:4] == 4'd9) && (q[11:8] == 4'd9);

    assign ena[1] = inc1;
    assign ena[2] = inc2;
    assign ena[3] = inc3;

    reg [15:0] q_reg;
    assign q = q_reg;

    always @(posedge clk) begin
        if (reset) begin
            q_reg <= 16'd0;
        end else begin
            // ones digit
            if (q_reg[3:0] == 4'd9)
                q_reg[3:0] <= 4'd0;
            else
                q_reg[3:0] <= q_reg[3:0] + 4'd1;

            // tens digit
            if (ena[1]) begin
                if (q_reg[7:4] == 4'd9)
                    q_reg[7:4] <= 4'd0;
                else
                    q_reg[7:4] <= q_reg[7:4] + 4'd1;
            end

            // hundreds digit
            if (ena[2]) begin
                if (q_reg[11:8] == 4'd9)
                    q_reg[11:8] <= 4'd0;
                else
                    q_reg[11:8] <= q_reg[11:8] + 4'd1;
            end

            // thousands digit
            if (ena[3]) begin
                if (q_reg[15:12] == 4'd9)
                    q_reg[15:12] <= 4'd0;
                else
                    q_reg[15:12] <= q_reg[15:12] + 4'd1;
            end
        end
    end

endmodule

