module TopModule (
    input  clk,
    input  areset,
    input  x,
    output z
);

    // One-hot state encoding: bit 0 = A, bit 1 = B
    reg [1:0] state, next_state;

    localparam A_IDX = 0;
    localparam B_IDX = 1;

    // Next-state logic
    always @(*) begin
        next_state = 2'b00;
        if (state[A_IDX]) begin
            if (x)
                next_state[B_IDX] = 1'b1;
            else
                next_state[A_IDX] = 1'b1;
        end
        if (state[B_IDX]) begin
            next_state[B_IDX] = 1'b1;
        end
    end

    // State register with asynchronous active-high reset
    always @(posedge clk or posedge areset) begin
        if (areset)
            state <= 2'b01;
        else
            state <= next_state;
    end

    // Mealy output
    assign z = (state[A_IDX] & x) | (state[B_IDX] & ~x);

endmodule

