    input  clk,
    input  reset,
    input  data,
    output start_shifting
);

    localparam S0    = 3'd0,  // no match
               S1    = 3'd1,  // seen 1
               S11   = 3'd2,  // seen 11
               S110  = 3'd3,  // seen 110
