module TopModule (
    input  clk,
    input  aresetn,
    input  x,
    output z
);

    // States: S0 = no progress, S1 = seen "1", S2 = seen "10"
    localparam S0 = 2'd0;
    localparam S1 = 2'd1;
    localparam S2 = 2'd2;

    reg [1:0] state, next_state;

    // State register with active-low asynchronous reset
    always @(posedge clk or negedge aresetn) begin
        if (!aresetn)
            state <= S0;
        else
            state <= next_state;
    end

    // Next-state logic
    always @(*) begin
        case (state)
            S0: next_state = x ? S1 : S0;
            S1: next_state = x ? S1 : S2;
            S2: next_state = x ? S1 : S0;
            default: next_state = S0;
        endcase
    end

    // Mealy output: asserted when in S2 and x = 1
    assign z = (state == S2) && x;

endmodule

