module TopModule (
    input clk,
    input reset,
    input ena,
    output reg pm,
    output reg [7:0] hh,
    output reg [7:0] mm,
    output reg [7:0] ss
);

    wire ss_wrap = (ss == 8'h59);
    wire mm_wrap = (mm == 8'h59);

    always @(posedge clk) begin
        if (reset) begin
            pm <= 1'b0;
            hh <= 8'h12;
            mm <= 8'h00;
            ss <= 8'h00;
        end
        else if (ena) begin
            // seconds
            if (ss_wrap) begin
                ss <= 8'h00;
            end
            else if (ss[3:0] == 4'd9) begin
                ss[3:0] <= 4'd0;
                ss[7:4] <= ss[7:4] + 4'd1;
            end
            else begin
                ss[3:0] <= ss[3:0] + 4'd1;
            end

            // minutes
            if (ss_wrap) begin
                if (mm_wrap) begin
                    mm <= 8'h00;
                end
                else if (mm[3:0] == 4'd9) begin
                    mm[3:0] <= 4'd0;
                    mm[7:4] <= mm[7:4] + 4'd1;
                end
                else begin
                    mm[3:0] <= mm[3:0] + 4'd1;
                end
            end

            // hours
            if (ss_wrap && mm_wrap) begin
                if (hh == 8'h12) begin
                    hh <= 8'h01;
                end
                else if (hh == 8'h09) begin
                    hh <= 8'h10;
                end
                else if (hh == 8'h11) begin
                    hh <= 8'h12;
                    pm <= ~pm;
                end
                else begin
                    hh[3:0] <= hh[3:0] + 4'd1;
                end
            end
        end
    end

endmodule

