    localparam S1   = 4'd3;
    localparam S2   = 4'd4;
    localparam G1   = 4'd5;
    localparam G2   = 4'd6;
    localparam GOK  = 4'd7;
    localparam GBAD = 4'd8;

    reg [3:0] state, next;

    always @(*) begin
        case (state)
            A:       next = F;
            F:       next = S0;
            S0:      next = x ? S1 : S0;
            S1:      next = x ? S1 : S2;
            S2:      next = x ? G1 : S0;
            G1:      next = y ? GOK : G2;
            G2:      next = y ? GOK : GBAD;
            GOK:     next = GOK;
            GBAD:    next = GBAD;
            default: next = A;
        endcase
    end

    always @(posedge clk) begin
        if (!resetn)
            state <= A;
        else
            state <= next;
    end

    assign f = (state == F);
    assign g = (state == G1) || (state == G2) || (state == GOK);

