    input  clk,
    input  reset,
    input  [2:0] s,
    output fr2,
    output fr1,
    output fr0,
    output dfr
);

    localparam BELOW  = 3'd0;
    localparam B_UP   = 3'd1;
    localparam B_DOWN = 3'd2;
    localparam C_UP   = 3'd3;
    localparam C_DOWN = 3'd4;
    localparam ABOVE  = 3'd5;

    reg [2:0] state, next_state;

    always @(*) begin
        next_state = state;
        case (s)
            3'b000: next_state = BELOW;
            3'b001: begin
                case (state)
                    BELOW:   next_state = B_UP;
                    B_UP:    next_state = B_UP;
                    B_DOWN:  next_state = B_DOWN;
                    default: next_state = B_DOWN;
                endcase
            end
            3'b011: begin
                case (state)
                    BELOW:   next_state = C_UP;
                    B_UP:    next_state = C_UP;
                    B_DOWN:  next_state = C_UP;
                    C_UP:    next_state = C_UP;
                    C_DOWN:  next_state = C_DOWN;
                    default: next_state = C_DOWN;
                endcase
            end
            3'b111: next_state = ABOVE;
            default: next_state = state;
        endcase
    end

    always @(posedge clk) begin
        if (reset)
            state <= BELOW;
        else
            state <= next_state;
    end

    assign fr2 = (state == BELOW);
    assign fr1 = (state == BELOW) || (state == B_UP) || (state == B_DOWN);
    assign fr0 = (state != ABOVE);
    assign dfr = (state == BELOW) || (state == B_UP) || (state == C_UP);

