module TopModule (
  input  clk,
  input  d,
  output q
);

  reg p;
  reg n;

  // On rising edge, store d XOR n so that p ^ n == d
  always @(posedge clk)
    p <= d ^ n;

  // On falling edge, store d XOR p so that p ^ n == d
  always @(negedge clk)
    n <= d ^ p;

  // Output is the XOR of both registers, reflecting the most recent edge's capture
  assign q = p ^ n;

endmodule

