    input  clk,
    input  areset,
    input  x,
    output z
);

    localparam A = 2'd0;  // no '1' seen yet, output 0
    localparam B = 2'd1;  // after first '1', output 1
    localparam C = 2'd2;  // after first '1', output 0

    reg [1:0] state, next_state;

    always @(*) begin
        case (state)
            A: next_state = x ? B : A;
            B: next_state = x ? C : B;
            C: next_state = x ? C : B;
            default: next_state = A;
        endcase
    end

    always @(posedge clk or posedge areset) begin
        if (areset)
            state <= A;
        else
            state <= next_state;
    end

    assign z = (state == B);

endmodule

