module TopModule (
    input clk,
    input load,
    input [255:0] data,
    output reg [255:0] q
);

    reg [255:0] next;
    integer r, c, dr, dc, rr, cc;
    reg [3:0] cnt;

    always @(*) begin
        for (r = 0; r < 16; r = r + 1) begin
            for (c = 0; c < 16; c = c + 1) begin
                cnt = 4'd0;
                for (dr = -1; dr <= 1; dr = dr + 1) begin
                    for (dc = -1; dc <= 1; dc = dc + 1) begin
                        if (!(dr == 0 && dc == 0)) begin
                            rr = (r + dr + 16) % 16;
                            cc = (c + dc + 16) % 16;
                            cnt = cnt + q[rr*16 + cc];
                        end
                    end
                end
                case (cnt)
                    4'd2: next[r*16 + c] = q[r*16 + c];
                    4'd3: next[r*16 + c] = 1'b1;
                    default: next[r*16 + c] = 1'b0;
                endcase
            end
        end
    end

    always @(posedge clk) begin
        if (load)
            q <= data;
        else
            q <= next;
    end

endmodule

