module TopModule (
    input  wire       clk,
    input  wire       areset,

    input  wire       predict_valid,
    input  wire [6:0] predict_pc,
    output wire       predict_taken,
    output wire [6:0] predict_history,

    input  wire       train_valid,
    input  wire       train_taken,
    input  wire       train_mispredicted,
    input  wire [6:0] train_history,
    input  wire [6:0] train_pc
);

    reg [1:0] pht [0:127];
    reg [6:0] ghr;

    wire [6:0] predict_idx;
    wire [6:0] train_idx;

    assign predict_idx     = predict_pc ^ ghr;
    assign train_idx       = train_pc ^ train_history;
    assign predict_taken   = pht[predict_idx][1];
    assign predict_history = ghr;

    integer i;

    // Global history register
    always @(posedge clk or posedge areset) begin
        if (areset) begin
            ghr <= 7'd0;
        end else begin
            if (train_valid && train_mispredicted)
                ghr <= {train_history[5:0], train_taken};
            else if (predict_valid)
                ghr <= {ghr[5:0], predict_taken};
        end
    end

    // Pattern history table
    always @(posedge clk or posedge areset) begin
        if (areset) begin
            for (i = 0; i < 128; i = i + 1)
                pht[i] <= 2'b01;
        end else begin
            if (train_valid) begin
                if (train_taken) begin
                    if (pht[train_idx] != 2'b11)
                        pht[train_idx] <= pht[train_idx] + 2'b01;
                end else begin
                    if (pht[train_idx] != 2'b00)
                        pht[train_idx] <= pht[train_idx] - 2'b01;
                end
            end
        end
    end

endmodule

