    input  areset,
    input  bump_left,
    input  bump_right,
    input  ground,
    input  dig,
    output walk_left,
    output walk_right,
    output aaah,
    output digging
);

    localparam LEFT   = 3'd0,
               RIGHT  = 3'd1,
               FALL_L = 3'd2,
               FALL_R = 3'd3,
               DIG_L  = 3'd4,
               DIG_R  = 3'd5,
               SPLAT  = 3'd6;

    reg [2:0] state, next_state;
    reg [4:0] fall_cnt;

    always @(*) begin
        next_state = state;
        case (state)
            LEFT: begin
                if (!ground)
                    next_state = FALL_L;
                else if (dig)
                    next_state = DIG_L;
                else if (bump_left)
                    next_state = RIGHT;
                else
                    next_state = LEFT;
            end
            RIGHT: begin
                if (!ground)
                    next_state = FALL_R;
                else if (dig)
                    next_state = DIG_R;
                else if (bump_right)
                    next_state = LEFT;
                else
                    next_state = RIGHT;
            end
            FALL_L: begin
                if (ground)
                    next_state = (fall_cnt >= 5'd20) ? SPLAT : LEFT;
                else
                    next_state = FALL_L;
            end
            FALL_R: begin
                if (ground)
                    next_state = (fall_cnt >= 5'd20) ? SPLAT : RIGHT;
                else
                    next_state = FALL_R;
            end
            DIG_L: begin
                if (!ground)
                    next_state = FALL_L;
                else
                    next_state = DIG_L;
            end
            DIG_R: begin
                if (!ground)
                    next_state = FALL_R;
                else
                    next_state = DIG_R;
            end
            SPLAT: next_state = SPLAT;
            default: next_state = LEFT;
        endcase
    end

    always @(posedge clk or posedge areset) begin
        if (areset)
            state <= LEFT;
        else
            state <= next_state;
    end

    // Counts the number of cycles spent in a falling state (saturating)
    always @(posedge clk or posedge areset) begin
        if (areset)
            fall_cnt <= 5'd0;
        else if (state == FALL_L || state == FALL_R) begin
            if (fall_cnt != 5'd31)
